window.SR_DATA = [{"lg":"nfl","n":"Chris Samuels","y":2000,"rd":1,"pk":3,"tm":"Washington","col":"Alabama","pos":"Offensive tackle","size":"6-5, 314 lb","g":141,"stat":"9 seasons as a starter","hon":["6x Pro Bowl"],"kind":"star","v":63,"id":"SamuCh00","angle":"glow","rep":"A franchise left tackle carved straight out of a quarry. Allows sacks about as often as a lunar eclipse. Mirrors speed rushers like a ballroom instructor, then finishes blocks like a bouncer at last call. The feet are light, the hands are heavy, the attitude is correct. Draft him and do not think about the left side again for a decade.","proj":"Projection: perennial Pro Bowl blind side. The quarterback's favorite person.","right":true},{"lg":"nfl","n":"Tom Brady","y":2000,"rd":6,"pk":199,"tm":"New England Patriots","col":"Michigan","pos":"Quarterback","size":"6-4, 225 lb","g":335,"stat":"89,214 passing yards, 649 TD, 212 INT","hon":["15x Pro Bowl","3x All-Pro"],"kind":"steal","v":184,"id":"BradTo00","angle":"pan","rep":"Physically, this is the body of a substitute teacher who quit the gym in March. Runs the 40 like he is looking for his car in a parking garage. Throwing motion is tidy and decisions are fine, yet his own coaches kept auditioning a shiny younger option behind him. Shows poise, which is what we say when there is nothing else to say. Lacks elite everything.","proj":"Projection: training camp arm. Excellent at holding clipboards.","right":false},{"lg":"nfl","n":"LaDainian Tomlinson","y":2001,"rd":1,"pk":5,"tm":"San Diego Chargers","col":"TCU","pos":"Running back","size":"5-10, 215 lb","g":170,"stat":"13,684 rushing yards, 145 TD","hon":["5x Pro Bowl","3x All-Pro","Hall of Fame"],"kind":"star","v":129,"id":"TomlLa00","angle":"glow","rep":"The kind of workhorse back who makes a stat sheet look like a typo. Led the nation in rushing twice against a schedule that did not always deserve him, and made it look like recess. Vision, balance, soft hands out of the backfield, and a jump cut that should require a permit. Small-program concerns are noted and rejected. Hand him the ball forty times and go get lunch.","proj":"Projection: first-ballot everything. Will rewrite the touchdown page of the record book.","right":true},{"lg":"nfl","n":"Richard Seymour","y":2001,"rd":1,"pk":6,"tm":"New England Patriots","col":"Georgia","pos":"Defensive end","size":"6-6, 317 lb","g":164,"stat":"57.5 sacks, 326 solo tackles","hon":["7x Pro Bowl","3x All-Pro","Hall of Fame"],"kind":"star","v":91,"id":"SeymRi00","angle":"pan","rep":"Enormous, long and athletic, which is great, because the sack totals read like a rounding error. Spent his college career eating double teams and holding the point, a noble profession appreciated by defensive coordinators and literally nobody else. Taking a guy this early who produced this little is the kind of move that gets a talk radio host a raise. Nice frame. Where are the plays?","proj":"Projection: high-floor run stuffer. Fans will hate the pick by lunch.","right":false},{"lg":"nfl","n":"Adrian Wilson","y":2001,"rd":3,"pk":64,"tm":"Arizona Cardinals","col":"North Carolina St.","pos":"Defensive back","size":"6-3, 230 lb","g":181,"stat":"27 interceptions, 730 solo tackles","hon":["5x Pro Bowl","1x All-Pro"],"kind":"steal","v":68,"id":"WilsAd99","angle":"pan","rep":"A tall, rangy safety who hits like the ball carrier owes him money, though his angles suggest a man reading a map upside down. Plenty of tools, and a toolbox full of loose screws. Will blow up a screen pass, then bite on a play fake from the parking lot. Special teams demon until somebody teaches him geometry.","proj":"Projection: core special teamer. Occasional spectacular collision, frequent wrong gap.","right":false},{"lg":"nfl","n":"Steve Smith Sr.","y":2001,"rd":3,"pk":74,"tm":"Carolina Panthers","col":"Utah","pos":"Wide receiver","size":"5-9, 195 lb","g":219,"stat":"1031 catches, 14,731 yards, 81 TD","hon":["5x Pro Bowl","2x All-Pro"],"kind":"steal","v":102,"id":"SmitSt01","angle":"pan","rep":"Built like a fire hydrant that took up kickboxing. Took the junior college detour, then spent his time mostly catching kicks and the occasional pass. Has quickness and a short fuse, which is a fine combination for a hockey enforcer. At this size, NFL corners will reroute him into the stands. A return specialist with ambitions, and ambitions do not beat press coverage.","proj":"Projection: return man. Will out-argue more defenders than he outruns.","right":false},{"lg":"nfl","n":"Julius Peppers","y":2002,"rd":1,"pk":2,"tm":"Carolina Panthers","col":"North Carolina","pos":"Defensive end","size":"6-7, 295 lb","g":266,"stat":"159.5 sacks, 557 solo tackles","hon":["9x Pro Bowl","3x All-Pro","Hall of Fame"],"kind":"star","v":130,"id":"PeppJu99","angle":"glow","rep":"Built like a power forward who wandered onto the field and stayed out of spite. A size and speed combination that makes scouts check the stopwatch for fresh batteries. Spent his winters on the hardwood, which explains the footwork and the hands that swat passes like flies. Occasionally takes a series off, but even his off series are terrifying. Unblockable in the way weather is unblockable.","proj":"Projection: double-digit sacks for fifteen years. Tackles will file complaints.","right":true},{"lg":"nfl","n":"Andre Johnson","y":2003,"rd":1,"pk":3,"tm":"Houston Texans","col":"Miami (FL)","pos":"Wide receiver","size":"6-3, 229 lb","g":193,"stat":"1062 catches, 14,185 yards, 70 TD","hon":["7x Pro Bowl","2x All-Pro","Hall of Fame"],"kind":"star","v":94,"id":"JohnAn02","angle":"glow","rep":"Ran a 40 that made the stopwatch question itself, at a size usually reserved for linebackers. Comes out of a receiver factory where he was simply the newest luxury model off the line. Big, fast, physical and quiet, which scouts love because he never says anything to ruin it. Catches through contact and keeps running like the contact was a rumor.","proj":"Projection: true number one. Thousand-yard seasons even with a bad quarterback.","right":true},{"lg":"nfl","n":"Lance Briggs","y":2003,"rd":3,"pk":68,"tm":"Chicago Bears","col":"Arizona","pos":"Linebacker","size":"6-1, 244 lb","g":173,"stat":"15 sacks, 944 solo tackles","hon":["7x Pro Bowl","1x All-Pro"],"kind":"steal","v":98,"id":"BrigLa99","angle":"pan","rep":"An undersized linebacker who ran his 40 like he was carrying groceries up a hill. Plays faster than he times, which is the nicest thing you can say about a guy who times slow. Instincts are good and tackling is reliable, but none of it matters when an NFL guard climbs to the second level and erases him. A special teams type with a firm handshake.","proj":"Projection: special teams lifer. Might start eventually, against everyone's wishes.","right":false},{"lg":"nfl","n":"Jason Witten","y":2003,"rd":3,"pk":69,"tm":"Dallas Cowboys","col":"Tennessee","pos":"Tight end","size":"6-6, 263 lb","g":271,"stat":"1228 catches, 13,046 yards, 74 TD","hon":["11x Pro Bowl","2x All-Pro"],"kind":"steal","v":80,"id":"WittJa00","angle":"pan","rep":"A big, willing blocker with the straight-line speed of an armoire on casters. Leaving school early, which is bold for a guy whose separation skills consist of leaning. Hands are reliable, effort is admirable, and he will block a defensive end on purpose, which is rare. But a tight end who cannot run is just a tackle with a smaller paycheck.","proj":"Projection: blocking tight end. Twelve catches a year, all of them gritty.","right":false},{"lg":"nfl","n":"Asante Samuel","y":2003,"rd":4,"pk":120,"tm":"New England Patriots","col":"Central Florida","pos":"Defensive back","size":"5-10, 185 lb","g":157,"stat":"51 interceptions, 398 solo tackles","hon":["4x Pro Bowl","1x All-Pro"],"kind":"steal","v":74,"id":"SamuAs20","angle":"pan","rep":"A small-school corner who gambles like he has a system at the blackjack table. Jumps routes with total confidence, which works great until a double move sends him into the next county. Undersized, tackles like he is stepping around a puddle, and the competition level is a giant asterisk. Ball skills are real. Discipline is theoretical.","proj":"Projection: nickel back. Gives up a big one every third Sunday.","right":false},{"lg":"nfl","n":"Robert Mathis","y":2003,"rd":5,"pk":138,"tm":"Indianapolis Colts","col":"Alabama A&M","pos":"Defensive end","size":"6-2, 245 lb","g":192,"stat":"123 sacks, 408 solo tackles","hon":["5x Pro Bowl","1x All-Pro"],"kind":"steal","v":67,"id":"MathRo20","angle":"pan","rep":"A tiny defensive end from the lower subdivision who racked up sacks against linemen who sell insurance in the offseason. At this weight he gets mistaken for a linebacker, then a safety, then a team manager. Quick first step, sure, but NFL tackles will engulf him like a beanbag chair. A situational rusher with a nice motor and no place to park it.","proj":"Projection: third-down specialist, if he finds a position by Labor Day.","right":false},{"lg":"nfl","n":"Larry Fitzgerald","y":2004,"rd":1,"pk":3,"tm":"Arizona Cardinals","col":"Pittsburgh","pos":"Wide receiver","size":"6-3, 218 lb","g":263,"stat":"1432 catches, 17,492 yards, 121 TD","hon":["11x Pro Bowl","1x All-Pro","Hall of Fame"],"kind":"star","v":93,"id":"FitzLa00","angle":"glow","rep":"The best hands I have ever seen, and I have watched a lot of hands. Catches anything near his area code, often one-handed, often with a defender attached to his jersey. Barely two years out of high school and already finished, like a kid who skipped grades because the teacher ran out of material. Not a burner, does not need to be. Polished, smart, absurdly competitive.","proj":"Projection: Hall of Fame. Will catch passes until roughly age forty.","right":true},{"lg":"nfl","n":"Philip Rivers","y":2004,"rd":1,"pk":4,"tm":"New York Giants","col":"North Carolina St.","pos":"Quarterback","size":"6-5, 228 lb","g":247,"stat":"63,984 passing yards, 425 TD, 212 INT","hon":["8x Pro Bowl"],"kind":"star","v":150,"id":"RivePh00","angle":"pan","rep":"Throws the football like a man skipping stones while being chased. The release starts somewhere near his hip and arrives at an angle that defies every textbook. Four-year starter, enormous production, competitive to the point of yelling, but that delivery will get batted down by any lineman taller than a mailbox. Smart. Tough. Weird. Very, very weird.","proj":"Projection: polarizing starter. Will lead the league in batted passes and chirping.","right":false},{"lg":"nfl","n":"Jared Allen","y":2004,"rd":4,"pk":126,"tm":"Kansas City Chiefs","col":"Idaho St.","pos":"Defensive end","size":"6-6, 255 lb","g":187,"stat":"136 sacks, 503 solo tackles","hon":["5x Pro Bowl","4x All-Pro","Hall of Fame"],"kind":"steal","v":101,"id":"AlleJa22","angle":"pan","rep":"A lower-subdivision pass rusher with the long hair, wild eyes and 40 time of a guy chasing an ice cream truck in flip-flops. Racked up sacks against linemen who probably doubled as the long snapper. Tough, nasty, relentless and slow. His best trait is wanting it, which is not measurable and is also not a position.","proj":"Projection: practice squad heartthrob. Possible career as a long snapper.","right":false},{"lg":"nfl","n":"Vincent Jackson","y":2005,"rd":2,"pk":61,"tm":"San Diego Chargers","col":"Northern Colorado","pos":"Wide receiver","size":"6-5, 230 lb","g":155,"stat":"540 catches, 9,080 yards, 57 TD","hon":["3x Pro Bowl"],"kind":"steal","v":77,"id":"JackVi00","angle":"pan","rep":"A huge receiver from a Division II program, which means he was mostly covered by guys majoring in accounting. Former hoops player, so he can box out, which helps if they ever let receivers set screens. His route tree has two branches and one of them is broken. Raw does not begin to describe it. This is sushi.","proj":"Projection: developmental project. Red zone dunk contest participant only.","right":false},{"lg":"nfl","n":"Frank Gore","y":2005,"rd":3,"pk":65,"tm":"San Francisco 49ers","col":"Miami (FL)","pos":"Running back","size":"5-9, 212 lb","g":241,"stat":"16,000 rushing yards, 81 TD","hon":["5x Pro Bowl"],"kind":"steal","v":94,"id":"GoreFr00","angle":"glow","rep":"Before the knee trouble, this was the most explosive back in the country, the kind of runner who makes defensive coordinators update their resumes. Lower body built like a wine barrel, vision like a hawk with a grudge, and a stubborn refusal to fall down. The medical file is thick, sure. The talent file is thicker. Take the risk, then send me a thank-you card.","proj":"Projection: workhorse back, if healthy. And if healthy is doing heavy lifting.","right":true},{"lg":"nfl","n":"Richie Incognito","y":2005,"rd":3,"pk":81,"tm":"St. Louis Rams","col":"Oregon","pos":"Guard","size":"6-3, 325 lb","g":164,"stat":"10 seasons as a starter","hon":["4x Pro Bowl"],"kind":"steal","v":62,"id":"IncoRi20","angle":"pan","rep":"A mauler with a mean streak so wide it has its own zip code. Will finish a block, then finish it again, then start a second argument with the linebacker. The strength is real, the feet are fine, and the technique occasionally takes the afternoon off to go yell at somebody. Flags follow him like seagulls follow a fishing boat. High ceiling, low fuse.","proj":"Projection: starting guard with a personal-foul subscription.","right":false},{"lg":"nfl","n":"Jay Ratliff","y":2005,"rd":7,"pk":224,"tm":"Dallas Cowboys","col":"Auburn","pos":"Defensive end","size":"6-4, 303 lb","g":122,"stat":"35 sacks, 195 solo tackles","hon":["4x Pro Bowl","1x All-Pro"],"kind":"steal","v":55,"id":"RatlJa20","angle":"pan","rep":"An undersized defensive end who looks like he should be a tackle and plays like he cannot decide. Spent his college days as a rotational body, the kind who shows up in the box score under miscellaneous. Quick off the ball and the effort is good, but at this weight NFL guards will use him as a decorative rug. Last-round flier, emphasis on flier.","proj":"Projection: camp body. Honorary captain of the scout team.","right":false},{"lg":"nfl","n":"Ryan Fitzpatrick","y":2005,"rd":7,"pk":250,"tm":"St. Louis Rams","col":"Harvard","pos":"Quarterback","size":"6-2, 228 lb","g":166,"stat":"34,990 passing yards, 223 TD, 169 INT","hon":[],"kind":"steal","v":78,"id":"FitzRy00","angle":"pan","rep":"A brainy quarterback from a school better known for producing senators than starters. Aced every test except the one with a stopwatch, and his arm has the velocity of a strongly worded letter. Mobile, tough, and clearly smarter than the scouts evaluating him, which we resent. Will spend his career learning playbooks, mostly for other teams.","proj":"Projection: eternal backup. Will own many different team polos.","right":false},{"lg":"nfl","n":"Jahri Evans","y":2006,"rd":4,"pk":108,"tm":"New Orleans Saints","col":"Bloomsburg","pos":"Offensive tackle","size":"6-4, 318 lb","g":183,"stat":"12 seasons as a starter","hon":["6x Pro Bowl","4x All-Pro"],"kind":"steal","v":114,"id":"EvanJa21","angle":"pan","rep":"A Division II lineman whose competition level makes the tape look like a men's league scrimmage. Big, strong and visibly bored, because nobody across from him was a real problem. Hand technique is raw, and every snap he looks like he is moving a couch up a staircase. The jump from this level to Sundays is not a jump. It is a pole vault without a pole.","proj":"Projection: practice squad, then backup guard if the pole ever arrives.","right":false},{"lg":"nfl","n":"Brandon Marshall","y":2006,"rd":4,"pk":119,"tm":"Denver Broncos","col":"Central Florida","pos":"Wide receiver","size":"6-5, 232 lb","g":179,"stat":"970 catches, 12,351 yards, 83 TD","hon":["6x Pro Bowl","1x All-Pro"],"kind":"steal","v":83,"id":"MarsBr00","angle":"pan","rep":"A former safety who wandered over to receiver, and the routes still look like a guy trying to tackle the end zone. Big, physical and fast enough, but the drops come in clusters like bad news. Plays with an edge, which is great until it is not. One monster bowl game does not make a career, no matter how many times they replay it.","proj":"Projection: special teams body. Possible return to safety by Week 6.","right":false},{"lg":"nfl","n":"Elvis Dumervil","y":2006,"rd":4,"pk":126,"tm":"Denver Broncos","col":"Louisville","pos":"Defensive end","size":"5-11, 250 lb","g":162,"stat":"105.5 sacks, 263 solo tackles","hon":["5x Pro Bowl","2x All-Pro"],"kind":"steal","v":63,"id":"DumeEl20","angle":"pan","rep":"Led the country in sacks, then showed up to measurements at roughly the height of a mailbox. Arms are short, frame is compact, and NFL tackles will simply place a hand on his forehead and wait. Yes, he forced fumbles by the bushel. Productive college player, sure, but the NFL is not an all-you-can-eat buffet for guys this size.","proj":"Projection: situational rusher. Sacks will come, mostly in garbage time.","right":false},{"lg":"nfl","n":"Kyle Williams","y":2006,"rd":5,"pk":134,"tm":"Buffalo Bills","col":"LSU","pos":"Defensive tackle","size":"6-1, 303 lb","g":183,"stat":"48.5 sacks, 387 solo tackles","hon":["6x Pro Bowl"],"kind":"steal","v":79,"id":"WillKy20","angle":"pan","rep":"A short, squatty interior lineman whose arms seem to end at the elbows. Plays hard, low and with leverage, which is what you call it when a guy has no other choice. Faced elite competition every week and held his own, which is admirable and also exactly what a backup does. Wears out blockers, then gets worn out himself.","proj":"Projection: rotational tackle. Lunch-pail guy, lunch-pail ceiling.","right":false},{"lg":"nfl","n":"Calvin Johnson","y":2007,"rd":1,"pk":2,"tm":"Detroit Lions","col":"Georgia Tech","pos":"Wide receiver","size":"6-5, 237 lb","g":135,"stat":"731 catches, 11,619 yards, 83 TD","hon":["6x Pro Bowl","3x All-Pro","Hall of Fame"],"kind":"star","v":78,"id":"JohnCa00","angle":"glow","rep":"Built like a power forward, runs like a sprinter, catches like the ball owes him money. At this height and weight he ran a 40 that broke the brains of grown men holding stopwatches. Smart, humble and polished, a scout's dream wrapped in another scout's dream. If there is a flaw, it is that he will make your other receivers look like interns.","proj":"Projection: generational wideout. Corners will request trades.","right":true},{"lg":"nfl","n":"Joe Thomas","y":2007,"rd":1,"pk":3,"tm":"Cleveland Browns","col":"Wisconsin","pos":"Offensive tackle","size":"6-6, 312 lb","g":167,"stat":"10 seasons as a starter","hon":["10x Pro Bowl","6x All-Pro","Hall of Fame"],"kind":"star","v":85,"id":"ThomJo28","angle":"glow","rep":"The safest pick in this draft, and possibly in human history. A massive, athletic tackle with the feet of a figure skater and hands like a vise grip. Does everything the right way, technically and mentally, and his tape is boring in the most beautiful way possible. Will start on day one and barely miss a snap until the sun burns out.","proj":"Projection: a decade of Pro Bowls. Possibly on a bad team, perfectly.","right":true},{"lg":"nfl","n":"Adrian Peterson","y":2007,"rd":1,"pk":7,"tm":"Minnesota Vikings","col":"Oklahoma","pos":"Running back","size":"6-1, 220 lb","g":184,"stat":"14,918 rushing yards, 120 TD","hon":["7x Pro Bowl","4x All-Pro"],"kind":"star","v":101,"id":"PeteAd01","angle":"glow","rep":"Runs like he is trying to escape from the film room. Size, speed, power and pure violence in one upright package. Yes, the injuries cost him chunks of time and the running style invites hits, but the hits seem to regret it. Trampled college defenses as a freshman like they were cardboard cutouts. Feed him and watch the scoreboard panic.","proj":"Projection: MVP-caliber bell cow. Linebackers will start skipping film sessions.","right":true},{"lg":"nfl","n":"Marshal Yanda","y":2007,"rd":3,"pk":86,"tm":"Baltimore Ravens","col":"Iowa","pos":"Offensive tackle","size":"6-3, 305 lb","g":177,"stat":"10 seasons as a starter","hon":["8x Pro Bowl","2x All-Pro"],"kind":"steal","v":92,"id":"YandMa20","angle":"pan","rep":"A junior college transfer with a body built for moving furniture and a technique built for moving it badly. Plays tackle, but lacks the feet to handle real edge speed, so he gets sentenced to guard. Tough, mean and competitive, all the words we use for a guy with no elite trait. Nice farm strength, though. Very nice farm strength.","proj":"Projection: backup interior lineman. Will lift the weight room in silence.","right":false},{"lg":"nfl","n":"Jamaal Charles","y":2008,"rd":3,"pk":73,"tm":"Kansas City Chiefs","col":"Texas","pos":"Running back","size":"5-11, 199 lb","g":119,"stat":"7,563 rushing yards, 44 TD","hon":["4x Pro Bowl","2x All-Pro"],"kind":"steal","v":66,"id":"CharJa00","angle":"pan","rep":"A track star in shoulder pads who runs fast in straight lines and faster toward the sideline. Light frame, upright style, and a habit of putting the ball on the ground like a library book he is returning. Never quite became the bell cow everyone predicted. Electric in space, invisible between the tackles.","proj":"Projection: change-of-pace back. Ten carries, one highlight, one fumble.","right":false},{"lg":"nfl","n":"Josh Sitton","y":2008,"rd":4,"pk":135,"tm":"Green Bay Packers","col":"Central Florida","pos":"Offensive tackle","size":"6-3, 320 lb","g":148,"stat":"9 seasons as a starter","hon":["4x Pro Bowl"],"kind":"steal","v":81,"id":"SittJo20","angle":"pan","rep":"A big, thick tackle from a mid-level program with the lateral quickness of a parked bus. Edge rushers would turn him into a turnstile, so the projection is guard, which is draft code for nobody is sure. Strong hands, decent anchor, and a tendency to stand straight up like he just heard his name called in a dentist's waiting room. Day three body.","proj":"Projection: backup guard. Will wear a headset at practice.","right":false},{"lg":"nfl","n":"Matthew Slater","y":2008,"rd":5,"pk":153,"tm":"New England Patriots","col":"UCLA","pos":"Wide receiver","size":"6-0, 205 lb","g":239,"stat":"1 catches, 46 yards, 0 TD","hon":["10x Pro Bowl","2x All-Pro"],"kind":"steal","v":0,"id":"SlatMa00","angle":"pan","rep":"A receiver whose most productive route is straight down the field on kickoff coverage. Catches the ball about as often as a solar eclipse, and his best skill is sprinting full speed at a returner without hesitation. Fast, willing and annoying to block, which is a resume for a gunner, not a wideout. Admirable. Niche. Extremely niche.","proj":"Projection: will rarely catch a pass. Kickoff units will build shrines.","right":false},{"lg":"nfl","n":"Ndamukong Suh","y":2010,"rd":1,"pk":2,"tm":"Detroit Lions","col":"Nebraska","pos":"Defensive tackle","size":"6-4, 313 lb","g":199,"stat":"71.5 sacks, 392 solo tackles","hon":["5x Pro Bowl","3x All-Pro"],"kind":"star","v":100,"id":"SuhxNd99","angle":"glow","rep":"Possibly the most dominant college defensive lineman in years. Absurd strength, rare quickness, and a playing temperament best described as rabid. Single-handedly ruined game plans, including one memorable night when an entire offensive line looked like it was wearing roller skates. Plays with an edge that may need sanding. Rare, rare talent.","proj":"Projection: All-Pro interior wrecker. Will be fined occasionally, and proudly.","right":true},{"lg":"nfl","n":"Gerald McCoy","y":2010,"rd":1,"pk":3,"tm":"Tampa Bay Buccaneers","col":"Oklahoma","pos":"Defensive tackle","size":"6-4, 300 lb","g":140,"stat":"59.5 sacks, 235 solo tackles","hon":["6x Pro Bowl","1x All-Pro"],"kind":"star","v":69,"id":"McCoGe99","angle":"glow","rep":"An explosive, penetrating interior lineman with a first step that arrives before the snap count. Quick hands, great energy, and a smile that makes him the most likable person to ever ruin a guard's afternoon. Some say he floats a little against the run. Those people have not been blown into the backfield by him. Plug him in and forget about it.","proj":"Projection: multiple Pro Bowls. Quarterbacks will be cheerfully flattened.","right":true},{"lg":"nfl","n":"Trent Williams","y":2010,"rd":1,"pk":4,"tm":"Washington","col":"Oklahoma","pos":"Offensive tackle","size":"6-5, 320 lb","g":211,"stat":"15 seasons as a starter","hon":["12x Pro Bowl","3x All-Pro"],"kind":"star","v":109,"id":"WillTr21","angle":"glow","rep":"An athletic marvel who moves like a tight end in the body of a vending machine. Played both tackle spots, mirrored speed rushers in his sleep, and tested like a defensive end. Occasionally the technique wanders, but the feet always bring it home. If there is a better pure athlete at this position, he is a fictional character.","proj":"Projection: perennial Pro Bowl blind side. Hall of Fame chatter by thirty.","right":true},{"lg":"nfl","n":"Eric Berry","y":2010,"rd":1,"pk":5,"tm":"Kansas City Chiefs","col":"Tennessee","pos":"Defensive back","size":"6-0, 212 lb","g":89,"stat":"14 interceptions, 377 solo tackles","hon":["5x Pro Bowl","3x All-Pro"],"kind":"star","v":50,"id":"BerrEr99","angle":"glow","rep":"The rangiest, most instinctive safety prospect in many years. Plays center field, the box, the slot, and probably the concession stand. A ball hawk with return ability, hits with total commitment, and leads the defense like a captain in a war movie. Some will say safeties do not go this high. Those people are wrong and should stop saying it.","proj":"Projection: Pro Bowl safety. Locker room mayor from day one.","right":true},{"lg":"nfl","n":"Jimmy Graham","y":2010,"rd":3,"pk":95,"tm":"New Orleans Saints","col":"Miami (FL)","pos":"Tight end","size":"6-7, 265 lb","g":197,"stat":"719 catches, 8,545 yards, 89 TD","hon":["5x Pro Bowl","1x All-Pro"],"kind":"steal","v":61,"id":"GrahJi00","angle":"pan","rep":"A basketball player who discovered football roughly forty-five minutes ago. Spent most of college on the hardwood, then played one season of football and handled passes like hot casseroles. Blocking is a rumor and the routes are a sketch on a napkin. Great at jumping, which is exactly what scouts said about the last fourteen hoopers who washed out.","proj":"Projection: practice squad project. Possible return to rebounding.","right":false},{"lg":"nfl","n":"Everson Griffen","y":2010,"rd":4,"pk":100,"tm":"Minnesota Vikings","col":"USC","pos":"Defensive end","size":"6-3, 273 lb","g":170,"stat":"85.5 sacks, 286 solo tackles","hon":["4x Pro Bowl"],"kind":"steal","v":67,"id":"GrifEv99","angle":"pan","rep":"A top recruit with an NFL body who mostly showed it off on the sideline. The tape has flashes, followed by long stretches where he seems to be playing a different, calmer sport. Leaving early on potential alone, which is like quitting your job because of a fortune cookie. The motor runs hot and cold, mostly lukewarm.","proj":"Projection: rotational end. Flashes in August, vanishes by November.","right":false},{"lg":"nfl","n":"Geno Atkins","y":2010,"rd":4,"pk":120,"tm":"Cincinnati Bengals","col":"Georgia","pos":"Defensive tackle","size":"6-1, 300 lb","g":161,"stat":"75.5 sacks, 228 solo tackles","hon":["8x Pro Bowl","2x All-Pro"],"kind":"steal","v":89,"id":"AtkiGe99","angle":"pan","rep":"A short, compact defensive tackle who never quite became the focal point of his own defensive line. Tested well, but so does my neighbor's riding mower. At this height NFL guards will lean on him until he becomes part of the turf. Quick, yes. Explosive in drills, sure. But sub-package depth looks like the ceiling, and the ceiling is low.","proj":"Projection: rotational depth. Nobody will ever sculpt a bust of him.","right":false},{"lg":"nfl","n":"Kam Chancellor","y":2010,"rd":5,"pk":133,"tm":"Seattle Seahawks","col":"Virginia Tech","pos":"Defensive back","size":"6-3, 225 lb","g":109,"stat":"12 interceptions, 421 solo tackles","hon":["4x Pro Bowl"],"kind":"steal","v":49,"id":"ChanKa99","angle":"pan","rep":"Built like a linebacker playing safety, and covers like a linebacker playing safety. Hips swivel like a filing cabinet. Will absolutely destroy anyone who catches a pass in front of him, but that pass is going to get caught. A former quarterback still learning the position, which is never a sentence you want in a defensive back evaluation.","proj":"Projection: special teams thumper. Covers tight ends for one quarter, max.","right":false},{"lg":"nfl","n":"Antonio Brown","y":2010,"rd":6,"pk":195,"tm":"Pittsburgh Steelers","col":"Central Michigan","pos":"Wide receiver","size":"5-10, 185 lb","g":146,"stat":"928 catches, 12,291 yards, 83 TD","hon":["7x Pro Bowl","4x All-Pro"],"kind":"steal","v":92,"id":"BrowAn04","angle":"pan","rep":"An undersized receiver from a mid-major who did his best work against defenses still learning each other's names. Return skills are nice and the routes are quick, yet the 40 time makes you wonder whether the stopwatch was napping. Small, light, and late-round for a reason. Carries the confidence of a top-ten pick, and that math rarely works out.","proj":"Projection: return specialist. Will punt-return his way onto a roster, briefly.","right":false},{"lg":"nfl","n":"Von Miller","y":2011,"rd":1,"pk":2,"tm":"Denver Broncos","col":"Texas A&M","pos":"Linebacker","size":"6-3, 245 lb","g":210,"stat":"138.5 sacks, 465 solo tackles","hon":["8x Pro Bowl","3x All-Pro"],"kind":"star","v":105,"id":"MillVo00","angle":"glow","rep":"A twitched-up edge rusher with the bend of a contortionist and the first step of a getaway driver. Moved to a stand-up rush role and immediately started collecting quarterbacks like baseball cards. Tested like a superhero and plays like one who enjoys the job. Some want more against the run. Some want everything. Take the guy who makes left tackles weep.","proj":"Projection: elite pass rusher from day one. Tackles will request help.","right":true},{"lg":"nfl","n":"A.J. Green","y":2011,"rd":1,"pk":4,"tm":"Cincinnati Bengals","col":"Georgia","pos":"Wide receiver","size":"6-4, 207 lb","g":158,"stat":"727 catches, 10,514 yards, 70 TD","hon":["7x Pro Bowl"],"kind":"star","v":77,"id":"GreeA.00","angle":"glow","rep":"Long, smooth and graceful, a wideout who glides like he is standing on a moving walkway. Plucks the ball at its highest point with hands softer than a hotel pillow. The slender build raises questions about press coverage, but the body control is absurd and the concentration is spooky. Every scout I know drew little hearts in his margin.","proj":"Projection: immediate WR1. Highlight catches every Sunday, minimal drama.","right":true},{"lg":"nfl","n":"Patrick Peterson","y":2011,"rd":1,"pk":5,"tm":"Arizona Cardinals","col":"LSU","pos":"Defensive back","size":"6-1, 203 lb","g":201,"stat":"36 interceptions, 571 solo tackles","hon":["8x Pro Bowl","3x All-Pro"],"kind":"star","v":103,"id":"PetePa00","angle":"glow","rep":"A corner built like a safety who runs like a sprinter and returns kicks like he invented them. A rare size and speed combination at the position, plus ball skills and a confidence level visible from the upper deck. Occasionally grabby against quicker receivers, but that is a technique fix, not a talent problem. Elite size, elite speed, elite swagger.","proj":"Projection: shutdown corner and electric returner. Pro Bowls early and often.","right":true},{"lg":"nfl","n":"Julio Jones","y":2011,"rd":1,"pk":6,"tm":"Atlanta Falcons","col":"Alabama","pos":"Wide receiver","size":"6-3, 220 lb","g":166,"stat":"914 catches, 13,703 yards, 66 TD","hon":["7x Pro Bowl","2x All-Pro"],"kind":"star","v":101,"id":"JoneJu02","angle":"glow","rep":"A muscle-car receiver with the frame of a safety and the speed of a rumor. Ran a blistering 40 and jumped out of the gym, then it turned out there was a broken bone in his foot during the workout, which is either a red flag or the toughest thing I have ever heard. Blocks like a tight end. The hands wobble now and then. Who cares.","proj":"Projection: true number one wideout. Coordinators will lose sleep.","right":true},{"lg":"nfl","n":"Justin Houston","y":2011,"rd":3,"pk":70,"tm":"Kansas City Chiefs","col":"Georgia","pos":"Linebacker","size":"6-3, 270 lb","g":170,"stat":"112 sacks, 409 solo tackles","hon":["4x Pro Bowl","1x All-Pro"],"kind":"steal","v":74,"id":"HousJu00","angle":"glow","rep":"A long, explosive edge rusher who led his defense in sacks and tormented tackles who probably still see him in their sleep. First-round tape, first-round testing, first-round motor. Whatever pushes him down the board has nothing to do with what happens between the whistles. Whoever grabs him late will look brilliant and very lucky.","proj":"Projection: double-digit sacker. Somebody is getting a bargain.","right":true},{"lg":"nfl","n":"Jurrell Casey","y":2011,"rd":3,"pk":77,"tm":"Tennessee Titans","col":"USC","pos":"Defensive tackle","size":"6-1, 305 lb","g":142,"stat":"51 sacks, 332 solo tackles","hon":["5x Pro Bowl"],"kind":"steal","v":72,"id":"CaseJu00","angle":"pan","rep":"An undersized defensive tackle who plays with leverage because nature gave him no other option. Leaving early after a solid but quiet career, with short arms, average burst, and a body type that screams rotational lunch pail. Plays hard, rarely makes the splash play, and will get displaced by NFL guards who eat players like him as an appetizer.","proj":"Projection: two-down run plugger. Steady, anonymous, gone in four years.","right":false},{"lg":"nfl","n":"Richard Sherman","y":2011,"rd":5,"pk":154,"tm":"Seattle Seahawks","col":"Stanford","pos":"Defensive back","size":"6-3, 205 lb","g":144,"stat":"37 interceptions, 385 solo tackles","hon":["5x Pro Bowl","3x All-Pro"],"kind":"steal","v":97,"id":"SherRi00","angle":"pan","rep":"A converted wideout who is still learning which direction to backpedal. Tall, long and stiff, with hips that turn like a cruise ship in a narrow channel. Talks a big game, and the game itself is about medium. Physical at the line, but once a quick receiver gets by him, the only thing he can catch is his breath.","proj":"Projection: special teams body. Will talk his way onto a roster.","right":false},{"lg":"nfl","n":"Jason Kelce","y":2011,"rd":6,"pk":191,"tm":"Philadelphia Eagles","col":"Cincinnati","pos":"Center","size":"6-3, 295 lb","g":193,"stat":"12 seasons as a starter","hon":["7x Pro Bowl","6x All-Pro"],"kind":"steal","v":102,"id":"KelcJa00","angle":"pan","rep":"A center who weighs about as much as a large refrigerator, minus the ice maker. A former walk-on who ran a 40 that would embarrass some tight ends, which is lovely, but NFL nose tackles will treat him like a lawn chair. Smart, nimble, aggressive. Also small. Very, very small for this job.","proj":"Projection: backup center. Will get bulldozed with a smile.","right":false},{"lg":"nfl","n":"Russell Wilson","y":2012,"rd":3,"pk":75,"tm":"Seattle Seahawks","col":"Wisconsin","pos":"Quarterback","size":"5-11, 206 lb","g":205,"stat":"46,966 passing yards, 353 TD, 114 INT","hon":["10x Pro Bowl"],"kind":"steal","v":140,"id":"WilsRu00","angle":"pan","rep":"The tape is outstanding, the leadership is real, and the deep ball is gorgeous. Then you stand next to him and realize you can see right over his head. A quarterback this short will throw passes directly into the facemasks of defensive linemen. He also split time with a second sport, which suggests his heart may be at the ballpark.","proj":"Projection: career backup. Maybe a fine minor-league second baseman.","right":false},{"lg":"nfl","n":"Demario Davis","y":2012,"rd":3,"pk":77,"tm":"New York Jets","col":"Arkansas St.","pos":"Linebacker","size":"6-2, 239 lb","g":234,"stat":"47 sacks, 979 solo tackles","hon":["2x Pro Bowl","1x All-Pro"],"kind":"steal","v":104,"id":"DaviDe00","angle":"pan","rep":"A small-school linebacker who tested like a track athlete and tackled like he was apologizing. Gets lost in the wash against bigger competition, struggles to shed blocks, and reads plays a half-beat late, which at the next level is a full touchdown early for the opponent. Athletic, sure. So is my mail carrier.","proj":"Projection: special teams contributor. Will run very fast to the wrong gap.","right":false},{"lg":"nfl","n":"T.Y. Hilton","y":2012,"rd":3,"pk":92,"tm":"Indianapolis Colts","col":"Florida International","pos":"Wide receiver","size":"5-10, 183 lb","g":146,"stat":"638 catches, 9,812 yards, 53 TD","hon":["4x Pro Bowl"],"kind":"steal","v":72,"id":"HiltT.00","angle":"pan","rep":"A tiny speedster from a program whose highlights air at 2 a.m. on a channel nobody gets. Light enough to blow away on a breezy day, and NFL corners will reroute him like airline luggage. Good returner, quick in and out of breaks, but at this size every hit is a gamble with his collarbones.","proj":"Projection: return man and gadget wideout. Ten catches, one reverse.","right":false},{"lg":"nfl","n":"Kirk Cousins","y":2012,"rd":4,"pk":102,"tm":"Washington","col":"Michigan St.","pos":"Quarterback","size":"6-3, 209 lb","g":181,"stat":"46,577 passing yards, 314 TD, 136 INT","hon":["4x Pro Bowl"],"kind":"steal","v":102,"id":"CousKi00","angle":"pan","rep":"A tall, earnest pocket passer with an arm that is technically sufficient. Reads defenses beautifully, then throws into them anyway, especially when the stakes rise. The leadership is great, the interview is great, the haircut is great. The interceptions are also great, in number. Will win the press conference and lose the fourth quarter.","proj":"Projection: quality backup. Beloved by the quarterback room snack table.","right":false},{"lg":"nfl","n":"Lane Johnson","y":2013,"rd":1,"pk":4,"tm":"Philadelphia Eagles","col":"Oklahoma","pos":"Offensive tackle","size":"6-6, 325 lb","g":171,"stat":"12 seasons as a starter","hon":["6x Pro Bowl","2x All-Pro"],"kind":"star","v":89,"id":"JohnLa01","angle":"glow","rep":"A former quarterback and tight end who grew into an offensive tackle the way a puppy grows into its paws. Tested like a defensive end, moves like a basketball player, and keeps the body control of a guy who used to throw spirals. Still learning the nuance, but the raw material is staggering. Draft the feet, coach the rest.","proj":"Projection: All-Pro right tackle. Will mirror edge rushers for a decade.","right":true},{"lg":"nfl","n":"Travis Kelce","y":2013,"rd":3,"pk":63,"tm":"Kansas City Chiefs","col":"Cincinnati","pos":"Tight end","size":"6-5, 250 lb","g":198,"stat":"1104 catches, 13,345 yards, 84 TD","hon":["11x Pro Bowl","4x All-Pro"],"kind":"steal","v":94,"id":"KelcTr00","angle":"pan","rep":"A former quarterback turned tight end with one strong season and a lot of question marks. Runs routes like he is improvising jazz, which is lovely until the quarterback needs to know where he will be. Blocking is a work in progress, and the work has not progressed. Talented and loose, a flier for teams that enjoy gambling.","proj":"Projection: backup tight end. Celebrations will outnumber catches.","right":false},{"lg":"nfl","n":"Terron Armstead","y":2013,"rd":3,"pk":75,"tm":"New Orleans Saints","col":"Ark-Pine Bluff","pos":"Offensive tackle","size":"6-5, 304 lb","g":135,"stat":"10 seasons as a starter","hon":["5x Pro Bowl"],"kind":"steal","v":67,"id":"ArmsTe00","angle":"pan","rep":"A tiny-school tackle who ran a 40 that made scouts drop their coffee, and then you watch the tape and realize he was blocking people who sell timeshares. An athletic freak with weak competition and a technique still in its rough draft. Turning a track star into a left tackle takes years. Most teams do not have years.","proj":"Projection: developmental swing tackle. Forever excellent at combine drills.","right":false},{"lg":"nfl","n":"Keenan Allen","y":2013,"rd":3,"pk":76,"tm":"San Diego Chargers","col":"California","pos":"Wide receiver","size":"6-2, 211 lb","g":177,"stat":"1084 catches, 12,309 yards, 71 TD","hon":["6x Pro Bowl"],"kind":"steal","v":80,"id":"AlleKe00","angle":"glow","rep":"A big, crafty receiver who runs routes like he has the defense's playbook in his back pocket. Rarely the fastest guy on the field, never the one getting jammed, and the hands swallow the ball whole. A knee injury and a slow workout will scare off the stopwatch crowd. Their loss. Somebody gets a first-round technician at a discount.","proj":"Projection: possession WR1. Defensive backs will spin in circles annually.","right":true},{"lg":"nfl","n":"David Bakhtiari","y":2013,"rd":4,"pk":109,"tm":"Green Bay Packers","col":"Colorado","pos":"Offensive tackle","size":"6-4, 310 lb","g":131,"stat":"9 seasons as a starter","hon":["3x Pro Bowl","2x All-Pro"],"kind":"steal","v":84,"id":"BakhDa00","angle":"pan","rep":"An early-entry tackle with arms that measure like a T. rex at a job interview. Quick feet, decent anchor, and he plays with a fun, slightly unhinged energy. But long rushers will reach his chest before he reaches theirs, every single time. Guard projection, if that. Too light, too short-armed, too early.","proj":"Projection: backup guard. Long-armed rushers will haunt his dreams.","right":false},{"lg":"nfl","n":"Kyle Juszczyk","y":2013,"rd":4,"pk":130,"tm":"Baltimore Ravens","col":"Harvard","pos":"Running back","size":"6-2, 235 lb","g":212,"stat":"234 rushing yards, 6 TD","hon":["10x Pro Bowl","2x All-Pro"],"kind":"steal","v":21,"id":"JuszKy00","angle":"pan","rep":"A brainy, versatile blocking back who majored in something hard and plays a position nobody uses. Fullback, tight end, H-back, wedge buster, team pencil sharpener. Smart and tough, but the competition level is academic, literally. The fullback is an endangered species, and this guy is the last good specimen in captivity.","proj":"Projection: special teamer and fullback. Fourteen career carries, total.","right":false},{"lg":"nfl","n":"Khalil Mack","y":2014,"rd":1,"pk":5,"tm":"Oakland Raiders","col":"Buffalo","pos":"Linebacker","size":"6-3, 269 lb","g":185,"stat":"116 sacks, 492 solo tackles","hon":["9x Pro Bowl","3x All-Pro"],"kind":"star","v":105,"id":"MackKh00","angle":"glow","rep":"A small-school edge terror who ate a big-program opponent alive in a memorable season opener, then kept eating all year. Explosive, powerful, violent with his hands, and somehow underrated despite rewriting the record book for forcing fumbles. The competition level is a knock until you watch him toss tackles around like laundry bags.","proj":"Projection: Defensive Player of the Year candidate. Tackles will consider retirement.","right":true},{"lg":"nfl","n":"Mike Evans","y":2014,"rd":1,"pk":7,"tm":"Tampa Bay Buccaneers","col":"Texas A&M","pos":"Wide receiver","size":"6-5, 231 lb","g":182,"stat":"893 catches, 13,472 yards, 111 TD","hon":["6x Pro Bowl"],"kind":"star","v":80,"id":"EvanMi00","angle":"glow","rep":"A gigantic receiver who played basketball until about five minutes ago and somehow already bullies cornerbacks. Catches contested balls like he is pulling rebounds off the glass. Not the cleanest route runner, and the top speed is more freight train than sports car, but in the red zone he is a cheat code. Drafting him is like adding a ladder to your playbook.","proj":"Projection: thousand-yard machine. Defensive backs will need step stools.","right":true},{"lg":"nfl","n":"Jarvis Landry","y":2014,"rd":2,"pk":63,"tm":"Miami Dolphins","col":"LSU","pos":"Wide receiver","size":"5-11, 202 lb","g":132,"stat":"713 catches, 7,870 yards, 38 TD","hon":["5x Pro Bowl"],"kind":"steal","v":56,"id":"LandJa00","angle":"pan","rep":"A tough, sure-handed receiver who ran his 40 like he was walking to the mailbox in slippers. Catches everything thrown his way, including passes meant for other people, and plays with real fight. But a slow, short slot guy in a league full of long, fast corners is a recipe for third-down disappointment.","proj":"Projection: possession slot, maybe. Will be open by exactly one yard.","right":false},{"lg":"nfl","n":"Trai Turner","y":2014,"rd":3,"pk":92,"tm":"Carolina Panthers","col":"LSU","pos":"Offensive line","size":"6-3, 320 lb","g":126,"stat":"9 seasons as a starter","hon":["5x Pro Bowl"],"kind":"steal","v":51,"id":"TurnTr01","angle":"pan","rep":"An early-entry interior lineman with power, a wide body, and technique that resembles a shopping cart with one bad wheel. Leaves school with limited starting experience and very real growing pains ahead. Strong at the point, lost on twists, and occasionally late off the ball like he forgot the snap count.","proj":"Projection: developmental guard. Two years on the bench, minimum.","right":false},{"lg":"nfl","n":"Danielle Hunter","y":2015,"rd":3,"pk":88,"tm":"Minnesota Vikings","col":"LSU","pos":"Defensive end","size":"6-5, 263 lb","g":160,"stat":"118.5 sacks, 383 solo tackles","hon":["5x Pro Bowl"],"kind":"steal","v":83,"id":"HuntDa01","angle":"pan","rep":"A sculpted, enormous pass rusher who tested like a superhero and produced like an intern. All the tools and very few sacks, which is like owning a sports car and only driving it to the end of the driveway. Young, long, fast and raw. Somebody will fall in love at the workout and fall out of love by October.","proj":"Projection: workout warrior. Will look fantastic in a uniform, mostly standing.","right":false},{"lg":"nfl","n":"Stefon Diggs","y":2015,"rd":5,"pk":146,"tm":"Minnesota Vikings","col":"Maryland","pos":"Wide receiver","size":"6-0, 191 lb","g":166,"stat":"966 catches, 11,718 yards, 78 TD","hon":["4x Pro Bowl","1x All-Pro"],"kind":"steal","v":90,"id":"DiggSt00","angle":"glow","rep":"A blue-chip recruit with sudden feet and the kind of route quickness that makes corners wobble at the knees. Injuries ate chunks of his college career and the quarterback play around him was often dreadful, but when healthy he was the most dangerous player on the field. Electric after the catch, fearless over the middle, competitive enough to argue with officials. Value pick.","proj":"Projection: legitimate starter. Somebody will regret letting him slide.","right":true},{"lg":"nfl","n":"Jalen Ramsey","y":2016,"rd":1,"pk":5,"tm":"Jacksonville Jaguars","col":"Florida St.","pos":"Cornerback","size":"6-1, 208 lb","g":159,"stat":"25 interceptions, 511 solo tackles","hon":["8x Pro Bowl","3x All-Pro"],"kind":"star","v":84,"id":"RamsJa00","angle":"glow","rep":"A long, fluid, nasty defensive back who can play corner, safety, nickel, and probably linebacker if asked nicely. A former track athlete with jumping events on the resume, size that fits any scheme, and the trash talk of a man who knows he is better than you. Occasionally grabby. Always confident. Every coordinator will want him, and his mouth.","proj":"Projection: All-Pro corner. Receivers will hear about it all week.","right":true},{"lg":"nfl","n":"Joe Thuney","y":2016,"rd":3,"pk":78,"tm":"New England Patriots","col":"North Carolina St.","pos":"Guard","size":"6-5, 301 lb","g":170,"stat":"10 seasons as a starter","hon":["4x Pro Bowl","3x All-Pro"],"kind":"steal","v":84,"id":"ThunJo00","angle":"pan","rep":"A college left tackle with arms built for a smaller human. Smart, versatile, and has played nearly every spot on the line, which is code for not elite at any of them. Plays with good leverage and pristine technique, the way an accountant files taxes, but power rushers will walk him straight back into the quarterback's lap.","proj":"Projection: swing backup. Will know the playbook better than the coaches.","right":false},{"lg":"nfl","n":"Dak Prescott","y":2016,"rd":4,"pk":135,"tm":"Dallas Cowboys","col":"Mississippi St.","pos":"Quarterback","size":"6-2, 230 lb","g":146,"stat":"37,840 passing yards, 256 TD, 97 INT","hon":["4x Pro Bowl"],"kind":"steal","v":104,"id":"PresDa01","angle":"pan","rep":"A big, sturdy dual-threat quarterback whose mechanics look like a garden hose with a kink in it. Ran an offense built around his legs, and his footwork in the pocket suggests he has rarely visited one. Tough, a great leader, beloved in every meeting room, but the accuracy comes and goes like a cell signal in a tunnel.","proj":"Projection: developmental backup. Great locker room guy, clipboard in hand.","right":false},{"lg":"nfl","n":"Matt Judon","y":2016,"rd":5,"pk":146,"tm":"Baltimore Ravens","col":"Grand Valley St.","pos":"Defensive end","size":"6-3, 265 lb","g":146,"stat":"72 sacks, 286 solo tackles","hon":["4x Pro Bowl"],"kind":"steal","v":63,"id":"JudoMa00","angle":"pan","rep":"A Division II sack leader who dominated linemen who will be managing car dealerships by June. Physically impressive, sure, but the tape looks like a highlight reel against a JV squad. The jump in competition is massive. The strength is real, the technique is nonexistent, and the learning curve is basically a cliff.","proj":"Projection: special teams, backup edge. Small-school legend forever.","right":false},{"lg":"nfl","n":"Tyreek Hill","y":2016,"rd":5,"pk":165,"tm":"Kansas City Chiefs","col":"West Alabama","pos":"Wide receiver","size":"5-10, 191 lb","g":145,"stat":"819 catches, 11,363 yards, 83 TD","hon":["8x Pro Bowl","5x All-Pro"],"kind":"steal","v":98,"id":"HillTy00","angle":"pan","rep":"A tiny Division II speedster who looks like he was designed in a wind tunnel. Pure track speed, which is nice, but routes are a concept he has heard described rather than practiced. Small, light and mostly a returner, he projects as a gadget guy who touches the ball four times a game and gets clobbered on two of them.","proj":"Projection: return specialist. Fastest guy on the bench.","right":false},{"lg":"nfl","n":"Myles Garrett","y":2017,"rd":1,"pk":1,"tm":"Cleveland Browns","col":"Texas A&M","pos":"Defensive end","size":"6-4, 272 lb","g":135,"stat":"125.5 sacks, 293 solo tackles","hon":["7x Pro Bowl","5x All-Pro"],"kind":"star","v":104,"id":"GarrMy00","angle":"glow","rep":"An absolute freak of a pass rusher who looks like he was assembled in a lab by a defensive coordinator with unlimited funding. Explosive first step, bend, power, length, and a workout that made the stopwatches blush. Some say he took plays off. Those plays were still better than most players' best snaps. Elite, elite prospect.","proj":"Projection: perennial All-Pro. Quarterbacks will develop a nervous twitch.","right":true},{"lg":"nfl","n":"Christian McCaffrey","y":2017,"rd":1,"pk":8,"tm":"Carolina Panthers","col":"Stanford","pos":"Running back","size":"5-11, 210 lb","g":119,"stat":"7,978 rushing yards, 70 TD","hon":["4x Pro Bowl","3x All-Pro"],"kind":"star","v":86,"id":"McCaCh01","angle":"glow","rep":"A Swiss Army knife with cleats. Runs between the tackles, catches like a receiver, returns kicks like a cheat code, and piled up all-purpose yardage like it was a hobby. Some worry about the frame and whether he can be a true workhorse. Those people should watch him run a route out of the backfield and then apologize.","proj":"Projection: multi-tool superstar. Fantasy players will draft him first for years.","right":true},{"lg":"nfl","n":"Dion Dawkins","y":2017,"rd":2,"pk":63,"tm":"Buffalo Bills","col":"Temple","pos":"Guard","size":"6-5, 320 lb","g":149,"stat":"9 seasons as a starter","hon":["5x Pro Bowl"],"kind":"steal","v":73,"id":"DawkDi00","angle":"pan","rep":"A college left tackle whose arms and footwork suggest he will be a guard, whether he likes it or not. Strong and enthusiastic, maybe too enthusiastic, celebrating pancakes like they are touchdowns. Struggles with speed off the edge and gets caught leaning. Inconsistent tape, middling competition, very high energy.","proj":"Projection: backup guard. Will cheer loudly from the sideline.","right":false},{"lg":"nfl","n":"Alvin Kamara","y":2017,"rd":3,"pk":67,"tm":"New Orleans Saints","col":"Tennessee","pos":"Running back","size":"5-10, 215 lb","g":132,"stat":"7,375 rushing yards, 63 TD","hon":["5x Pro Bowl"],"kind":"steal","v":79,"id":"KamaAl00","angle":"pan","rep":"A committee back who rarely got more than a handful of touches, which raises the question of whether his own coaches knew what they had, or knew exactly what they had. Shifty and slippery, sure, but never proven as a workhorse. Small sample size, limited tread, and a career built in someone else's shadow. Gadget player, at best.","proj":"Projection: third-down back. Some flash, mostly shadow.","right":false},{"lg":"nfl","n":"Trey Hendrickson","y":2017,"rd":3,"pk":103,"tm":"New Orleans Saints","col":"Florida Atlantic","pos":"Outside linebacker","size":"6-4, 265 lb","g":122,"stat":"83 sacks, 167 solo tackles","hon":["4x Pro Bowl","1x All-Pro"],"kind":"steal","v":58,"id":"HendTr00","angle":"pan","rep":"A small-school edge rusher who piled up sacks against linemen who mostly majored in sports management. High effort, decent first step, but short arms and stiff hips will limit him to effort plays against real tackles. The motor runs hot and the ceiling sits low. The kind of guy coaches love and stat sheets ignore.","proj":"Projection: rotational edge. Will make the roster through sheer stubbornness.","right":false},{"lg":"nfl","n":"George Kittle","y":2017,"rd":5,"pk":146,"tm":"San Francisco 49ers","col":"Iowa","pos":"Tight end","size":"6-4, 250 lb","g":131,"stat":"629 catches, 8,433 yards, 57 TD","hon":["7x Pro Bowl","2x All-Pro"],"kind":"steal","v":60,"id":"KittGe00","angle":"pan","rep":"A blocking tight end who caught passes about as often as the team mascot. Enthusiastic, physical and goofy, he blocks like it is personal and runs routes like they are optional. Tested surprisingly well, which tells you he can run fast when nobody is throwing him the ball. Will be a solid third tight end and a joyful special teamer.","proj":"Projection: blocking specialist. Ten catches a year, maximum.","right":false},{"lg":"nfl","n":"Quenton Nelson","y":2018,"rd":1,"pk":6,"tm":"Indianapolis Colts","col":"Notre Dame","pos":"Guard","size":"6-5, 330 lb","g":136,"stat":"8 seasons as a starter","hon":["8x Pro Bowl","3x All-Pro"],"kind":"star","v":79,"id":"NelsQu00","angle":"glow","rep":"The best guard prospect anyone has seen in ages, and I am counting the ones on video game covers. A people mover with violent hands who treats defensive tackles like folding chairs. Some say a guard should not go this early. Watch him drive a linebacker into the bench area and then explain why not.","proj":"Projection: day-one All-Pro. Pancakes will be served daily.","right":true},{"lg":"nfl","n":"Roquan Smith","y":2018,"rd":1,"pk":8,"tm":"Chicago Bears","col":"Georgia","pos":"Inside linebacker","size":"6-1, 235 lb","g":132,"stat":"23.5 sacks, 716 solo tackles","hon":["4x Pro Bowl","3x All-Pro"],"kind":"star","v":84,"id":"SmitRo07","angle":"glow","rep":"A sideline-to-sideline linebacker who plays at a speed that makes everyone else look like they are wading through syrup. Smaller than the prototype, sure, but instinctive, fast, and a tackling machine who rarely misses. Leads the defense with quiet intensity and diagnoses plays before the offense finishes the huddle. Plug and play.","proj":"Projection: tackling machine. Will run a defense for years.","right":true},{"lg":"nfl","n":"Fred Warner","y":2018,"rd":3,"pk":70,"tm":"San Francisco 49ers","col":"BYU","pos":"Outside linebacker","size":"6-3, 230 lb","g":128,"stat":"10.5 sacks, 630 solo tackles","hon":["4x Pro Bowl","4x All-Pro"],"kind":"steal","v":82,"id":"WarnFr00","angle":"pan","rep":"A safety-linebacker hybrid who is too small for one job and too slow for the other. Played a hybrid role in college, which is a polite way of saying nobody knew where to put him. Smart and quick in short bursts, but at this weight NFL linemen will use him as a speed bump. Special teams body with excellent posture.","proj":"Projection: core special teamer. Possibly a backup safety, eventually.","right":false},{"lg":"nfl","n":"Orlando Brown Jr.","y":2018,"rd":3,"pk":83,"tm":"Baltimore Ravens","col":"Oklahoma","pos":"Offensive tackle","size":"6-8, 350 lb","g":132,"stat":"8 seasons as a starter","hon":["4x Pro Bowl"],"kind":"steal","v":69,"id":"BrowOr00","angle":"pan","rep":"A massive tackle with good tape and a workout so slow and weak it will be studied by future generations as a cautionary tale. Bench reps that looked like a toddler moving a couch, and a 40 that was more of a stroll. The size is real and the technique is decent, but the stopwatch and the bar will haunt him.","proj":"Projection: backup swing tackle. May never run anywhere again.","right":false},{"lg":"nfl","n":"Maxx Crosby","y":2019,"rd":4,"pk":106,"tm":"Oakland Raiders","col":"Eastern Michigan","pos":"Defensive end","size":"6-5, 255 lb","g":117,"stat":"71.5 sacks, 285 solo tackles","hon":["5x Pro Bowl"],"kind":"steal","v":61,"id":"CrosMa00","angle":"pan","rep":"A tall, skinny edge rusher who looks like a lamppost in a uniform. Racked up sacks against small-time competition, and now he wants to do it against NFL tackles who outweigh him by a full mailman. Long, active and relentless, but light, and those tackles will lean on him until he folds like a road map.","proj":"Projection: situational rusher. Will need to eat a lot of pasta.","right":false},{"lg":"nfl","n":"Penei Sewell","y":2021,"rd":1,"pk":7,"tm":"Detroit Lions","col":"Oregon","pos":"Offensive line","size":"6-5, 335 lb","g":89,"stat":"5 seasons as a starter","hon":["4x Pro Bowl","3x All-Pro"],"kind":"star","v":64,"id":"SewePe00","angle":"glow","rep":"A massive, young tackle with the feet of a point guard and the hands of a car crusher. Sat out his final season and still looks like the best lineman in the draft. Tackles this size should not be able to move like this. He does, he knows it, and you can see it on every snap of the old tape.","proj":"Projection: perennial Pro Bowl. Will anchor a line for a decade.","right":true},{"lg":"nfl","n":"Creed Humphrey","y":2021,"rd":2,"pk":63,"tm":"Kansas City Chiefs","col":"Oklahoma","pos":"Offensive line","size":"6-4, 302 lb","g":91,"stat":"5 seasons as a starter","hon":["4x Pro Bowl","2x All-Pro"],"kind":"steal","v":51,"id":"HumpCr00","angle":"glow","rep":"A polished center with a wrestler's leverage, a defensive coordinator's brain, and hands that grab like vise grips. Smart, nasty and always on time, which is all you can ask from the man touching the ball every snap. Shorter arms, sure. Who cares? Centers this ready to start do not grow on trees.","proj":"Projection: day-one starter. Pro Bowl sooner than anyone expects.","right":true},{"lg":"nfl","n":"Amon-Ra St. Brown","y":2021,"rd":4,"pk":112,"tm":"Detroit Lions","col":"USC","pos":"Wide receiver","size":"6-0, 202 lb","g":89,"stat":"593 catches, 6,777 yards, 49 TD","hon":["4x Pro Bowl","2x All-Pro"],"kind":"steal","v":57,"id":"StxxAm00","angle":"pan","rep":"A polished, sure-handed slot receiver with the top speed of a reliable minivan. Runs crisp routes and catches everything, but separation against NFL corners will require a permission slip. Productive in a talented receiver room, though rarely the main attraction. Good hands, good effort, average everything else. A mid-round slot guy with a first-round handshake.","proj":"Projection: slot depth. Will get open, just not quickly.","right":false},{"lg":"nfl","n":"Courtney Brown","y":2000,"rd":1,"pk":1,"tm":"Cleveland Browns","col":"Penn St.","pos":"Defensive end","size":"6-4, 285 lb","g":61,"stat":"19 sacks, 156 solo tackles","hon":[],"kind":"bust","v":27,"id":"BrowCo22","angle":"glow","rep":"A once-a-decade edge freak. Sculpted at roughly 270 pounds and runs like a safety who swallowed a bigger safety. Set a school sack record, then made it look like he was holding back. Offensive tackles do not block him so much as file a formal complaint afterward. There is no flaw on the tape. We checked twice and asked a priest.","proj":"Projection: perennial All-Pro. Gold jacket fitting should be scheduled now.","right":false},{"lg":"nfl","n":"Peter Warrick","y":2000,"rd":1,"pk":4,"tm":"Cincinnati Bengals","col":"Florida St.","pos":"Wide receiver","size":"5-11, 192 lb","g":79,"stat":"275 catches, 2,991 yards, 18 TD","hon":[],"kind":"bust","v":27,"id":"WarrPe00","angle":"glow","rep":"The most elusive human being we have ever put a stopwatch on. Catches a slant and suddenly eleven defenders are tackling each other. Adds punt return value, slot value, gadget value, and probably real estate value. Biggest games produce his biggest highlights. Lacks only a weakness, which we have stopped looking for out of respect.","proj":"Projection: franchise playmaker. Will need a second trophy case by year three.","right":false},{"lg":"nfl","n":"Ron Dayne","y":2000,"rd":1,"pk":11,"tm":"New York Giants","col":"Wisconsin","pos":"Running back","size":"5-10, 245 lb","g":96,"stat":"3,722 rushing yards, 28 TD","hon":[],"kind":"bust","v":23,"id":"DaynRo00","angle":"glow","rep":"A battering ram with a student ID. Carries a frame north of 250 pounds and owns the kind of career rushing total that makes record books ask for a recount. Gets stronger in the fourth quarter while linebackers quietly reconsider their careers. Some worry about mileage. We say the tires were built for it.","proj":"Projection: thousand-yard workhorse for a decade. Bring extra mouthguards.","right":false},{"lg":"nfl","n":"David Terrell","y":2001,"rd":1,"pk":8,"tm":"Chicago Bears","col":"Michigan","pos":"Wide receiver","size":"6-3, 212 lb","g":54,"stat":"128 catches, 1,602 yards, 9 TD","hon":[],"kind":"bust","v":11,"id":"TerrDa00","angle":"glow","rep":"Tall, strong, and smooth, a big-bodied target who catches everything thrown in his zip code. His bowl-game tape is basically a trailer for a franchise receiver. Wins jump balls like he has a reservation for them. Corners who play him in press coverage should be checked for concussion symptoms of the soul. Day-one starter.","proj":"Projection: perennial Pro Bowl number one. Quarterbacks will send fruit baskets.","right":false},{"lg":"nfl","n":"Jamal Reynolds","y":2001,"rd":1,"pk":10,"tm":"Green Bay Packers","col":"Florida St.","pos":"Defensive end","size":"6-3, 260 lb","g":18,"stat":"3 sacks, 14 solo tackles","hon":[],"kind":"bust","v":3,"id":"ReynJa20","angle":"glow","rep":"The most decorated pass rusher in the country, and the hardware is fully earned. First step arrives before the snap count finishes. Some say he is a touch light for the edge. Those people have never watched a left tackle try to recover from this get-off. Lives in the backfield and should start paying rent.","proj":"Projection: double-digit sacks annually. Quarterbacks will develop nervous tics.","right":false},{"lg":"nfl","n":"Mike Williams","y":2002,"rd":1,"pk":4,"tm":"Buffalo Bills","col":"Texas","pos":"Offensive tackle","size":"6-7, 337 lb","g":59,"stat":"4 seasons as a starter","hon":[],"kind":"bust","v":24,"id":"WillMi22","angle":"glow","rep":"A building with feet. Roughly 370 pounds of trophy-winning tackle who moves like someone half his size and twice his attitude. Run blocking is a felony on tape: defenders are relocated against their will. Pass sets are wide enough to block out the sun. Versatile enough to play either tackle spot or guard, or serve as a load-bearing wall.","proj":"Projection: ten-year anchor. Pancake stats will need their own spreadsheet.","right":false},{"lg":"nfl","n":"Ryan Sims","y":2002,"rd":1,"pk":6,"tm":"Kansas City Chiefs","col":"North Carolina","pos":"Defensive tackle","size":"6-4, 315 lb","g":105,"stat":"8.5 sacks, 115 solo tackles","hon":[],"kind":"bust","v":22,"id":"SimsRy20","angle":"glow","rep":"Explosive interior penetrator with a first step that should be illegal in several states. Big enough to hold the point, quick enough to make guards look like they are wading through wet cement. Plays with a constant motor and shows up in the backfield like he was invited. Rare combination of size and snap at the position.","proj":"Projection: Pro Bowl three-technique. Centers will request transfers.","right":false},{"lg":"nfl","n":"Wendell Bryant","y":2002,"rd":1,"pk":12,"tm":"Arizona Cardinals","col":"Wisconsin","pos":"Defensive tackle","size":"6-5, 306 lb","g":29,"stat":"1.5 sacks, 33 solo tackles","hon":[],"kind":"bust","v":4,"id":"BryaWe20","angle":"glow","rep":"Quick-twitch interior disruptor who lives in opposing backfields. Gets off the ball so fast offensive linemen are still reading the play call. Heavy hands, good leverage, and a motor that does not believe in commercial breaks. Comes from a program that churns out tough, physical linemen, and he may be the toughest of the lot.","proj":"Projection: eight-year starter. Running backs will start bouncing outside on purpose.","right":false},{"lg":"nfl","n":"Charles Rogers","y":2003,"rd":1,"pk":2,"tm":"Detroit Lions","col":"Michigan St.","pos":"Wide receiver","size":"6-3, 220 lb","g":15,"stat":"36 catches, 440 yards, 4 TD","hon":[],"kind":"bust","v":4,"id":"RogeCh01","angle":"glow","rep":"The best receiver prospect in years, and it is not close. Six-foot-three with sprinter speed, the kind of combination usually found only in video games with the cheat codes on. Won the top receiver award and probably could have won it blindfolded. Long strides eat cushion like a buffet. Deep balls should simply be thrown in his general direction.","proj":"Projection: first-ballot Hall of Famer. Defensive coordinators will lose sleep and hair.","right":false},{"lg":"nfl","n":"Johnathan Sullivan","y":2003,"rd":1,"pk":6,"tm":"New Orleans Saints","col":"Georgia","pos":"Defensive tackle","size":"6-3, 315 lb","g":36,"stat":"1.5 sacks, 57 solo tackles","hon":[],"kind":"bust","v":10,"id":"SullJo23","angle":"glow","rep":"A massive interior presence who blossomed into a wrecking ball as an upperclassman. Over 310 pounds yet moves with the ease of a man jogging to the fridge. One dominant season was so loud it drowned out everything that came before it. Upside is basically limitless. The arrow is not just pointing up, it has achieved orbit.","proj":"Projection: anchor of a top-five defense. Guards should invest in ice baths.","right":false},{"lg":"nfl","n":"Jimmy Kennedy","y":2003,"rd":1,"pk":12,"tm":"St. Louis Rams","col":"Penn St.","pos":"Defensive tackle","size":"6-4, 302 lb","g":92,"stat":"8.5 sacks, 107 solo tackles","hon":[],"kind":"bust","v":16,"id":"KennJi21","angle":"glow","rep":"An enormous, decorated defensive tackle with All-America credentials and a frame from a Marvel storyboard. Six-foot-four and well over 300 pounds, he collapses pockets just by standing in them. When he turns it on, nobody in the country can block him. The occasional quiet snap is clearly strategic. He is saving energy for the pros.","proj":"Projection: perennial Pro Bowl run stuffer. Double teams will be mandatory by law.","right":false},{"lg":"nfl","n":"Reggie Williams","y":2004,"rd":1,"pk":9,"tm":"Jacksonville Jaguars","col":"Washington","pos":"Wide receiver","size":"6-4, 212 lb","g":79,"stat":"189 catches, 2,322 yards, 18 TD","hon":[],"kind":"bust","v":23,"id":"WillRe00","angle":"glow","rep":"Big, physical outside receiver who has been producing since the day he arrived on campus. Built like a power forward, catches the ball away from his body, and treats press coverage like a personal insult. Leaves school early because there is simply nothing left to prove. A true number one who brings the box-out game to the boundary.","proj":"Projection: decade-long go-to target. Corners will request zone coverage forever.","right":false},{"lg":"nfl","n":"Cadillac Williams","y":2005,"rd":1,"pk":5,"tm":"Tampa Bay Buccaneers","col":"Auburn","pos":"Running back","size":"5-11, 218 lb","g":81,"stat":"4,038 rushing yards, 21 TD","hon":[],"kind":"bust","v":28,"id":"WillCa02","angle":"glow","rep":"Elite vision and a cutback that leaves pursuit angles in shambles. Shares a backfield and still steals the show, which tells you everything. Hits the hole with violence, finishes runs with bad intentions, and keeps defenders guessing with a hitch-and-go jump cut that seems to defy physics. Will carry an offense on day one. Rookie award voters, save your ballot.","proj":"Projection: annual 1,500-yard back. Rookie of the Year speech already drafted.","right":false},{"lg":"nfl","n":"Troy Williamson","y":2005,"rd":1,"pk":7,"tm":"Minnesota Vikings","col":"South Carolina","pos":"Wide receiver","size":"6-1, 203 lb","g":49,"stat":"87 catches, 1,131 yards, 4 TD","hon":[],"kind":"bust","v":8,"id":"WillTr01","angle":"pan","rep":"Runs like his hair is on fire, catches like his hands are too. The stopwatch numbers are spectacular and the route tree is a twig. Sees a ball in the air and treats it like an unexpected bill. Track speed has never been in question. Whether he can play football at full speed with a ball arriving is very much still in committee.","proj":"Projection: decoy with a pension. Will clear safeties and miss passes.","right":true},{"lg":"nfl","n":"Mike Williams","y":2005,"rd":1,"pk":10,"tm":"Detroit Lions","col":"USC","pos":"Wide receiver","size":"6-5, 235 lb","g":56,"stat":"127 catches, 1,526 yards, 5 TD","hon":[],"kind":"bust","v":12,"id":"WillMi03","angle":"glow","rep":"A six-foot-five catch radius with a power forward's body and hands like oven mitts made of glue. Dominated as an underclassman against the best competition in the country. Some time away from game action is irrelevant: you cannot coach size and you cannot rust instincts. Red zone fades are basically free points. Corners will need a stepladder.","proj":"Projection: perennial red zone menace. Defensive backs will file height complaints.","right":false},{"lg":"nfl","n":"Matt Leinart","y":2006,"rd":1,"pk":10,"tm":"Arizona Cardinals","col":"USC","pos":"Quarterback","size":"6-5, 225 lb","g":33,"stat":"4,065 passing yards, 15 TD, 21 INT","hon":[],"kind":"bust","v":12,"id":"LeinMa00","angle":"glow","rep":"The most decorated college passer in recent memory, a proven winner with hardware in every room of the house. Poised, accurate, and unflappable in the biggest moments on the biggest stages. Arm strength is a manufactured concern from people who like stopwatches more than championships. Pro-ready from his first huddle. Simply knows how to win.","proj":"Projection: franchise quarterback for fifteen years. Maybe a few rings too.","right":false},{"lg":"nfl","n":"JaMarcus Russell","y":2007,"rd":1,"pk":1,"tm":"Oakland Raiders","col":"LSU","pos":"Quarterback","size":"6-6, 260 lb","g":31,"stat":"4,083 passing yards, 18 TD, 23 INT","hon":[],"kind":"bust","v":6,"id":"RussJa00","angle":"pan","rep":"Can throw a football into the next area code without moving his feet, and that is most of the résumé. A massive frame that seems to grow between weigh-ins, a cannon attached to it, and very few college starts to show for either. Scouts fell in love at one workout and stopped asking questions. The playbook will be a long-term reading project.","proj":"Projection: richest clipboard in league history. Arm talent, sadly, not included.","right":true},{"lg":"nfl","n":"Gaines Adams","y":2007,"rd":1,"pk":4,"tm":"Tampa Bay Buccaneers","col":"Clemson","pos":"Defensive end","size":"6-5, 258 lb","g":47,"stat":"13.5 sacks, 67 solo tackles","hon":[],"kind":"bust","v":17,"id":"AdamGa99","angle":"glow","rep":"Long, lean, explosive edge rusher who led his league in sacks while making it look like cardio. Has a bend around the corner usually reserved for gymnasts and garden hoses. Arms go on for days. Already reads offensive tackles like a bedtime story. Some want more bulk. We want to know why anyone would argue with this burst.","proj":"Projection: Pro Bowl edge rusher. Will retire tackles early and often.","right":false},{"lg":"nfl","n":"Jamaal Anderson","y":2007,"rd":1,"pk":8,"tm":"Atlanta Falcons","col":"Arkansas","pos":"Defensive end","size":"6-6, 280 lb","g":77,"stat":"7.5 sacks, 96 solo tackles","hon":[],"kind":"bust","v":20,"id":"AndeJa98","angle":"glow","rep":"A tall, long, still-growing defensive end with the frame of a prototype that escaped the lab. Six-foot-six, nearly 290 pounds, and only scratching the surface of his ability. The ceiling here is a vaulted cathedral. Arms are so long he can sack a quarterback from the parking lot. Dominant as a junior and still learning the position.","proj":"Projection: double-digit sacks by year two. Ceiling cannot be measured with current instruments.","right":false},{"lg":"nfl","n":"Amobi Okoye","y":2007,"rd":1,"pk":10,"tm":"Houston Texans","col":"Louisville","pos":"Defensive tackle","size":"6-2, 310 lb","g":87,"stat":"16 sacks, 118 solo tackles","hon":[],"kind":"bust","v":24,"id":"OkoyAm99","angle":"glow","rep":"Younger than some of the jerseys in our equipment room and already plays like a ten-year vet. A thick, powerful interior lineman with natural leverage and an absurd learning curve. Has started for years at an age when most prospects are still learning to parallel park. Imagine what he looks like at twenty-five. Then lock the doors.","proj":"Projection: decade-long Pro Bowl interior force. Possibly two decades, given the birth certificate.","right":false},{"lg":"nfl","n":"Vernon Gholston","y":2008,"rd":1,"pk":6,"tm":"New York Jets","col":"Ohio St.","pos":"Defensive end","size":"6-3, 260 lb","g":45,"stat":"0 sacks, 24 solo tackles","hon":[],"kind":"bust","v":6,"id":"GholVe99","angle":"pan","rep":"Looks like he was carved for a museum and, on many snaps, plays like he is guarding one. Workout numbers are hilarious: bench press reps for days, speed that has no business in a body this big. The tape is a mixtape: one game where he ruins a future first-round tackle, plenty of others where he spends the afternoon jogging.","proj":"Projection: combine legend, Sunday ghost. Zero sacks with flawless posture.","right":true},{"lg":"nfl","n":"Sedrick Ellis","y":2008,"rd":1,"pk":7,"tm":"New Orleans Saints","col":"USC","pos":"Defensive tackle","size":"6-1, 307 lb","g":70,"stat":"12.5 sacks, 99 solo tackles","hon":[],"kind":"bust","v":26,"id":"ElliSe99","angle":"glow","rep":"A thick, compact, violent interior lineman who lived in opponents' backfields for a perennial powerhouse. Dominated all-star week practices, folding centers like origami. Plays with leverage, quickness, and a motor that keeps running after the whistle. Played on a defense loaded with NFL talent and still stood out every single week. Plug-and-play nose who can rush.","proj":"Projection: perennial Pro Bowl tackle. Centers will consult attorneys.","right":false},{"lg":"nfl","n":"Derrick Harvey","y":2008,"rd":1,"pk":8,"tm":"Jacksonville Jaguars","col":"Florida","pos":"Defensive end","size":"6-5, 268 lb","g":52,"stat":"8 sacks, 72 solo tackles","hon":[],"kind":"bust","v":14,"id":"HarvDe99","angle":"glow","rep":"Long, quick, and at his best on the biggest possible stage, where he spent a championship night living in the quarterback's lap. Lean frame with room to add good weight. Gets off the ball like he has inside information. Natural pass rusher with bend, burst, and a big-game gene that you simply cannot teach. Dominant closer.","proj":"Projection: perennial double-digit sacker. Bring your title-game tape.","right":false},{"lg":"nfl","n":"Keith Rivers","y":2008,"rd":1,"pk":9,"tm":"Cincinnati Bengals","col":"USC","pos":"Linebacker","size":"6-2, 235 lb","g":74,"stat":"3 sacks, 189 solo tackles","hon":[],"kind":"bust","v":24,"id":"RiveKe99","angle":"glow","rep":"Fast, smart, sideline-to-sideline linebacker from a program that manufactures linebackers on an assembly line. Diagnoses plays before the quarterback finishes reading them. Covers tight ends, chases down backs, and lines everyone up like a hall monitor with a whistle. Never out of position. Never misses a tackle. Never, apparently, has a bad practice.","proj":"Projection: ten-year starter and defensive captain. Wears the green dot forever.","right":false},{"lg":"nfl","n":"Jason Smith","y":2009,"rd":1,"pk":2,"tm":"St. Louis Rams","col":"Baylor","pos":"Offensive tackle","size":"6-5, 308 lb","g":45,"stat":"2 seasons as a starter","hon":[],"kind":"bust","v":10,"id":"SmitJa22","angle":"glow","rep":"Converted tight end who now moves like a basketball forward in a 300-pound body. Nimble feet, long arms, and a nasty streak that shows up whenever a defender gets cute. Still learning the position and already dominant, which is frankly frightening. Plays with a mean that you cannot coach. A blindside protector for the next decade.","proj":"Projection: perennial Pro Bowl left tackle. Quarterback dry cleaning bills will plummet.","right":false},{"lg":"nfl","n":"Aaron Curry","y":2009,"rd":1,"pk":4,"tm":"Seattle Seahawks","col":"Wake Forest","pos":"Linebacker","size":"6-2, 255 lb","g":48,"stat":"5.5 sacks, 163 solo tackles","hon":[],"kind":"bust","v":16,"id":"CurrAa99","angle":"glow","rep":"The lowest-risk prospect we have ever evaluated. Built like a vending machine, runs like a safety, and hits like an alarm clock. Can rush the passer, drop in coverage, play the run, and probably coach special teams. Won the top award at his position and the hype has only grown. If he busts, we will eat this draft guide.","proj":"Projection: perennial Pro Bowler. Literally cannot miss. Please hold us to that.","right":false},{"lg":"nfl","n":"Darrius Heyward-Bey","y":2009,"rd":1,"pk":7,"tm":"Oakland Raiders","col":"Maryland","pos":"Wide receiver","size":"6-2, 210 lb","g":144,"stat":"202 catches, 2,897 yards, 16 TD","hon":[],"kind":"bust","v":23,"id":"HeywDa00","angle":"pan","rep":"The fastest man in any room he enters, and that is where the evaluation ends. Production was modest for someone who supposedly runs past everybody. Hands are a coin flip, routes look like they were drawn on a napkin during a fire drill. Stopwatches adore him. Footballs seem to have mixed feelings about the arrangement.","proj":"Projection: elite decoy, part-time receiver. Will win every training camp footrace.","right":true},{"lg":"nfl","n":"Aaron Maybin","y":2009,"rd":1,"pk":11,"tm":"Buffalo Bills","col":"Penn St.","pos":"Defensive end","size":"6-4, 240 lb","g":48,"stat":"6 sacks, 27 solo tackles","hon":[],"kind":"bust","v":5,"id":"MaybAa99","angle":"pan","rep":"One productive season, a frame that weighs in somewhere between a linebacker and a large golden retriever, and a big pile of potential. Explosive off the edge but disappears when a 320-pound tackle simply leans on him. Needs to add significant weight without losing the speed that makes him interesting. That is a lot of needs.","proj":"Projection: situational rusher. Sacks will be rare but the first step pops.","right":true},{"lg":"nfl","n":"Rolando McClain","y":2010,"rd":1,"pk":8,"tm":"Oakland Raiders","col":"Alabama","pos":"Linebacker","size":"6-4, 255 lb","g":65,"stat":"9.5 sacks, 288 solo tackles","hon":[],"kind":"bust","v":25,"id":"McClRo00","angle":"glow","rep":"The quarterback of a championship defense, an instinctive linebacker who makes every adjustment before the offense breaks the huddle. Thumps downhill, reads guards like a novel, and is never fooled by play action. Took home the top award at his position. Smarter than half the coordinators in the league and hits harder than the other half.","proj":"Projection: decade-long defensive leader. Future coaching staff material too.","right":false},{"lg":"nfl","n":"Jake Locker","y":2011,"rd":1,"pk":8,"tm":"Tennessee Titans","col":"Washington","pos":"Quarterback","size":"6-3, 223 lb","g":30,"stat":"4,967 passing yards, 27 TD, 22 INT","hon":[],"kind":"bust","v":15,"id":"LockJa00","angle":"glow","rep":"A tough, athletic quarterback who runs like a linebacker and is twice as competitive. Strong arm, quick feet, and the will to drag an overmatched supporting cast across the finish line. Accuracy numbers are a function of the supporting cast, not the man. Turned down early money to come back, which tells you everything about his heart.","proj":"Projection: franchise starter. Will win games on grit alone.","right":false},{"lg":"nfl","n":"Blaine Gabbert","y":2011,"rd":1,"pk":10,"tm":"Jacksonville Jaguars","col":"Missouri","pos":"Quarterback","size":"6-5, 235 lb","g":69,"stat":"9,487 passing yards, 51 TD, 50 INT","hon":[],"kind":"bust","v":17,"id":"GabbBl00","angle":"glow","rep":"Prototypical size, live arm, and the clean-cut look of a quarterback on a cereal box. Athletic enough to move the pocket and strong enough to fire into tight windows. Spread system concerns are overblown: the tools are simply too good. Calm demeanor that translates to the pros on day one. Coaches will love him.","proj":"Projection: ten-year franchise passer. Jerseys will fly off the shelves.","right":false},{"lg":"nfl","n":"Christian Ponder","y":2011,"rd":1,"pk":12,"tm":"Minnesota Vikings","col":"Florida St.","pos":"Quarterback","size":"6-2, 230 lb","g":38,"stat":"6,658 passing yards, 38 TD, 36 INT","hon":[],"kind":"bust","v":22,"id":"PondCh00","angle":"glow","rep":"The smartest quarterback in this class and possibly in the solar system. Collects degrees like box scores, processes defenses at the line, and runs a pro-style system with total command. Arm strength is adequate and athleticism is a sneaky plus. The minor injuries are behind him. A coordinator on the field with a coach's brain and a starter's poise.","proj":"Projection: long-term starter. Will understand his offense better than the offensive coordinator.","right":false},{"lg":"nfl","n":"Trent Richardson","y":2012,"rd":1,"pk":3,"tm":"Cleveland Browns","col":"Alabama","pos":"Running back","size":"5-9, 225 lb","g":46,"stat":"2,032 rushing yards, 17 TD","hon":[],"kind":"bust","v":17,"id":"RichTr00","angle":"glow","rep":"The best running back prospect in years. Built like a bowling ball with a grudge, he runs through arm tackles, over safeties, and around anyone foolish enough to try the first two. Has vision, burst, receiving chops, and pass protection. Linebackers who meet him in the hole should request hazard pay. A true three-down workhorse for a decade.","proj":"Projection: perennial All-Pro. Will run through walls and some foundations.","right":false},{"lg":"nfl","n":"Justin Blackmon","y":2012,"rd":1,"pk":5,"tm":"Jacksonville Jaguars","col":"Oklahoma St.","pos":"Wide receiver","size":"6-1, 210 lb","g":20,"stat":"93 catches, 1,280 yards, 6 TD","hon":[],"kind":"bust","v":9,"id":"BlacJu00","angle":"glow","rep":"Back-to-back winner of the top receiver award, a big, physical target who turns slants into touchdowns and corners into spectators. Strong hands, strong frame, strong opinions about who should have the ball. Dominates after the catch like a running back who got lost in a receivers meeting. Produces against everyone, every week.","proj":"Projection: perennial Pro Bowl receiver. Quarterbacks will simply throw it up.","right":false},{"lg":"nfl","n":"Morris Claiborne","y":2012,"rd":1,"pk":6,"tm":"Dallas Cowboys","col":"LSU","pos":"Defensive back","size":"5-11, 192 lb","g":85,"stat":"7 interceptions, 213 solo tackles","hon":[],"kind":"bust","v":25,"id":"ClaiMo00","angle":"glow","rep":"A former receiver who now treats the ball like it belongs to him. Instincts are off the charts, hips flip like a light switch, and he closes on throws with alarming confidence. Won the top defensive back award and earned every bit of it. Shuts down an entire side of the field. Quarterbacks will throw the other way.","proj":"Projection: perennial shutdown corner. Interceptions on speed dial.","right":false},{"lg":"nfl","n":"Luke Joeckel","y":2013,"rd":1,"pk":2,"tm":"Jacksonville Jaguars","col":"Texas A&M","pos":"Offensive tackle","size":"6-6, 307 lb","g":50,"stat":"3 seasons as a starter","hon":[],"kind":"bust","v":21,"id":"JoecLu00","angle":"glow","rep":"The most polished pass protector in the country. Spent his college career keeping a scrambling, highlight-reel quarterback upright, which is like babysitting a tornado. Feet are quick, hands are precise, and his technique belongs in an instructional video. Already won the top lineman award. Day-one left tackle with a ten-year shelf life.","proj":"Projection: perennial Pro Bowl blindside protector. Sleep easy, quarterbacks.","right":false},{"lg":"nfl","n":"Dion Jordan","y":2013,"rd":1,"pk":3,"tm":"Miami Dolphins","col":"Oregon","pos":"Defensive end","size":"6-6, 284 lb","g":63,"stat":"13.5 sacks, 82 solo tackles","hon":[],"kind":"bust","v":9,"id":"JordDi00","angle":"glow","rep":"An absurd athlete in a lean, six-foot-six frame. Rushes off the edge, drops into coverage, and covers slot receivers when he feels like showing off. Few college coaches knew how to use him, so the best football is clearly ahead. Minor shoulder concerns are just that: minor. Upside is the kind you write books about.","proj":"Projection: double-digit sack edge for a decade. Will also cover tight ends.","right":false},{"lg":"nfl","n":"Barkevious Mingo","y":2013,"rd":1,"pk":6,"tm":"Cleveland Browns","col":"LSU","pos":"Linebacker","size":"6-5, 238 lb","g":126,"stat":"12.5 sacks, 179 solo tackles","hon":[],"kind":"bust","v":24,"id":"MingBa00","angle":"glow","rep":"Bends around the edge like a drinking straw built by NASA. Explosive get-off, ridiculous length, and closing speed that turns quarterbacks into pinballs. Lean frame is a feature, not a bug: you do not want to add drag to a sports car. Plays on a defense full of future pros and still pops off the film.","proj":"Projection: Pro Bowl pass rusher. Weight room will finish the job.","right":false},{"lg":"nfl","n":"Jonathan Cooper","y":2013,"rd":1,"pk":7,"tm":"Arizona Cardinals","col":"North Carolina","pos":"Guard","size":"6-2, 308 lb","g":46,"stat":"2 seasons as a starter","hon":[],"kind":"bust","v":16,"id":"CoopJo01","angle":"glow","rep":"The rare guard who moves like a running back. Pulls across the formation with speed you would not believe from someone this size, gets to the second level, and erases linebackers like a typo. Technique is advanced, anchor is solid, and intelligence is through the roof. Interior line prospects do not come cleaner than this.","proj":"Projection: ten-year Pro Bowl guard. Linebackers will hide behind safeties.","right":false},{"lg":"nfl","n":"Tavon Austin","y":2013,"rd":1,"pk":8,"tm":"St. Louis Rams","col":"West Virginia","pos":"Wide receiver","size":"5-8, 185 lb","g":113,"stat":"244 catches, 2,239 yards, 16 TD","hon":[],"kind":"bust","v":26,"id":"AustTa00","angle":"glow","rep":"Undersized only in the measuring tape sense. Every time he touches the ball he is a threat to score from anywhere on the field, including the bench. Plays receiver, running back, and returner, and hits top speed in about one step. Defenders spend games grasping at air and their own pride. Create touches. Collect highlights. Repeat.","proj":"Projection: All-Pro weapon. Offensive coordinators will invent plays just for him.","right":false},{"lg":"nfl","n":"Dee Milliner","y":2013,"rd":1,"pk":9,"tm":"New York Jets","col":"Alabama","pos":"Defensive back","size":"6-0, 201 lb","g":21,"stat":"3 interceptions, 50 solo tackles","hon":[],"kind":"bust","v":6,"id":"MillDe00","angle":"glow","rep":"The top corner in the class from a program that wins championships for fun. Physical, fast, and polished in press-man coverage. Breaks on the ball with violence and finishes plays like a safety. Minor surgeries are routine maintenance on a high-performance machine. Has been covering future pros in practice for years, which is the real advantage.","proj":"Projection: perennial shutdown corner. Number one receivers will request trades.","right":false},{"lg":"nfl","n":"Chance Warmack","y":2013,"rd":1,"pk":10,"tm":"Tennessee Titans","col":"Alabama","pos":"Guard","size":"6-2, 323 lb","g":68,"stat":"3 seasons as a starter","hon":[],"kind":"bust","v":22,"id":"WarmCh00","angle":"glow","rep":"The best guard prospect in a generation, a road grader who simply moves human beings where he wants them. Built like a refrigerator that took up powerlifting, he blows defensive tackles out of the hole with a single violent punch. Rarely beaten, never moved backward. You do not draft guards this high unless they are this good.","proj":"Projection: decade-long Pro Bowler. Running backs will send him steak dinners.","right":false},{"lg":"nfl","n":"D.J. Hayden","y":2013,"rd":1,"pk":12,"tm":"Oakland Raiders","col":"Houston","pos":"Defensive back","size":"5-11, 190 lb","g":92,"stat":"4 interceptions, 282 solo tackles","hon":[],"kind":"bust","v":16,"id":"HaydDJ00","angle":"glow","rep":"Smooth, fluid cover corner who wins with instincts and quick feet. Reads routes like he got a copy of the playbook the night before. The competition level is a fair question, but the tape answers it: receivers do not get open, period. Willing tackler with ball skills to spare. Rare movement skills for the position.","proj":"Projection: day-one starting corner. Will erase receivers on every level.","right":false},{"lg":"nfl","n":"Greg Robinson","y":2014,"rd":1,"pk":2,"tm":"St. Louis Rams","col":"Auburn","pos":"Offensive tackle","size":"6-5, 330 lb","g":83,"stat":"5 seasons as a starter","hon":[],"kind":"bust","v":24,"id":"RobiGr01","angle":"glow","rep":"A massive, freakishly athletic tackle who moves defenders like furniture on moving day. Run blocking is a war crime against defensive ends, minus the actual war. Over 330 pounds, runs like a tight end, and is still just learning the finer points of pass protection. The ceiling is the roof of the stadium. Possibly the next level up.","proj":"Projection: perennial All-Pro tackle. Defensive ends will need therapy.","right":false},{"lg":"nfl","n":"Justin Gilbert","y":2014,"rd":1,"pk":8,"tm":"Cleveland Browns","col":"Oklahoma St.","pos":"Defensive back","size":"6-0, 202 lb","g":35,"stat":"1 interceptions, 36 solo tackles","hon":[],"kind":"bust","v":4,"id":"GilbJu00","angle":"glow","rep":"A long, fast, ball-hawking corner who doubles as a kickoff return terror. Speed is legitimately elite, hands are those of a receiver, and his instincts on deep throws are a gift. Quarterbacks who test him tend to hand him the ball and then apologize. Brings points on defense and special teams. Rare playmaker at the position.","proj":"Projection: Pro Bowl corner and return threat. Collects interceptions like stamps.","right":false},{"lg":"nfl","n":"Kevin White","y":2015,"rd":1,"pk":7,"tm":"Chicago Bears","col":"West Virginia","pos":"Wide receiver","size":"6-3, 216 lb","g":30,"stat":"28 catches, 397 yards, 0 TD","hon":[],"kind":"bust","v":3,"id":"WhitKe00","angle":"glow","rep":"A late bloomer who exploded into the most dangerous big receiver in the class. Six-foot-three and runs like a sprinter who got bored with the track. Turns short throws into long touchdowns and contested catches into routine ones. Only one massive season, sure, but the trajectory is pointing at the moon. Elite physical tools, elite finish.","proj":"Projection: perennial number one target. Arrow is up. Way up.","right":false},{"lg":"nfl","n":"Trae Waynes","y":2015,"rd":1,"pk":11,"tm":"Minnesota Vikings","col":"Michigan St.","pos":"Cornerback","size":"6-0, 190 lb","g":79,"stat":"7 interceptions, 226 solo tackles","hon":[],"kind":"bust","v":18,"id":"WaynTr00","angle":"glow","rep":"The fastest corner in the class and he plays exactly that fast. Long, tall, and aggressive at the line, he jams receivers like he is trying to return them to the store. Comes from a system that demanded press-man coverage on every snap. Grabby at times, but that is just enthusiasm. Shutdown upside is obvious.","proj":"Projection: Pro Bowl corner. Will turn number one receivers into tight ends.","right":false},{"lg":"nfl","n":"Eli Apple","y":2016,"rd":1,"pk":10,"tm":"New York Giants","col":"Ohio St.","pos":"Cornerback","size":"6-1, 203 lb","g":104,"stat":"6 interceptions, 313 solo tackles","hon":[],"kind":"bust","v":28,"id":"ApplEl00","angle":"glow","rep":"Young, long, and confident, a press corner who has been covering future NFL receivers in practice his whole career. Barely old enough to rent a car and already technically refined. Physical at the catch point, fluid in his turn. The ceiling is enormous given his age. Plug and play now, Pro Bowl later.","proj":"Projection: shutdown corner for a decade. Confidence alone worth a first round pick.","right":false},{"lg":"nfl","n":"Vernon Hargreaves III","y":2016,"rd":1,"pk":11,"tm":"Tampa Bay Buccaneers","col":"Florida","pos":"Cornerback","size":"5-10, 204 lb","g":69,"stat":"4 interceptions, 245 solo tackles","hon":[],"kind":"bust","v":18,"id":"HargVe00","angle":"glow","rep":"An instinctive, ball-hawking corner who started from his first day on campus and never gave the job back. Quick feet, fluid hips, and a feel for routes that seems borderline psychic. Not the tallest, but plays bigger than his measurements every week. Born to cover slot receivers and humble boundary ones. Polished and pro-ready.","proj":"Projection: perennial Pro Bowl corner. Instant upgrade to any secondary.","right":false},{"lg":"nfl","n":"Solomon Thomas","y":2017,"rd":1,"pk":3,"tm":"San Francisco 49ers","col":"Stanford","pos":"Defensive end","size":"6-2, 285 lb","g":138,"stat":"18.5 sacks, 147 solo tackles","hon":[],"kind":"bust","v":21,"id":"ThomSo00","angle":"glow","rep":"A versatile, high-motor defender who can line up anywhere from nose to edge and wreck a game from all of them. His bowl-game tape is a horror movie for offensive linemen. Strong hands, quick get-off, and a relentless motor that never seems to run low on fuel. Smart, technically refined, and ready now.","proj":"Projection: perennial double-digit sacker. Coordinators will move him everywhere.","right":false},{"lg":"nfl","n":"John Ross","y":2017,"rd":1,"pk":9,"tm":"Cincinnati Bengals","col":"Washington","pos":"Wide receiver","size":"5-11, 190 lb","g":38,"stat":"63 catches, 963 yards, 11 TD","hon":[],"kind":"bust","v":7,"id":"RossJo00","angle":"glow","rep":"The fastest football player alive, and possibly the fastest non-cheetah in history. Ran a forty that made stopwatches question their batteries. Not just a straight-line burner: crisp routes, sudden breaks, real production. Size is overrated when nobody can catch you. Previous knee issues are behind him, mostly. Defenses must account for him on every snap.","proj":"Projection: perennial deep threat. Safeties will retire from exhaustion.","right":false},{"lg":"nfl","n":"Josh Rosen","y":2018,"rd":1,"pk":10,"tm":"Arizona Cardinals","col":"UCLA","pos":"Quarterback","size":"6-4, 215 lb","g":24,"stat":"2,864 passing yards, 12 TD, 21 INT","hon":[],"kind":"bust","v":3,"id":"RoseJo01","angle":"glow","rep":"The most polished pure passer in the class. Mechanics are textbook, footwork is pristine, and the ball comes out like it was fired from a laser printer. Throws with anticipation that most pro quarterbacks would envy. Reads the field like he has already seen the answers. If you want a pocket passer, this is the one.","proj":"Projection: franchise quarterback. Will throw spirals in his sleep.","right":false},{"lg":"nfl","n":"Clelin Ferrell","y":2019,"rd":1,"pk":4,"tm":"Oakland Raiders","col":"Clemson","pos":"Defensive end","size":"6-4, 265 lb","g":101,"stat":"21 sacks, 98 solo tackles","hon":[],"kind":"bust","v":24,"id":"FerrCl00","angle":"glow","rep":"A refined, high-floor edge defender from a defensive line so loaded it should be studied by scientists. Technically clean, plays with excellent hand usage and a nonstop motor. Not flashy, just effective, which is exactly what you want at the top of the draft. Productive every year of his career. Zero risk, maximum reliability.","proj":"Projection: decade-long starter. A safe pick by every measurable standard.","right":false},{"lg":"nfl","n":"Patrick Ramsey","y":2002,"rd":1,"pk":32,"tm":"Washington","col":"Tulane","pos":"Quarterback","size":"6-2, 225 lb","g":37,"stat":"5,930 passing yards, 35 TD, 30 INT","hon":[],"kind":"bust","v":14,"id":"RamsPa00","angle":"glow","rep":"A strong-armed passer who threw for huge numbers in a pass-happy offense against whatever was put in front of him. Tough in the pocket, unafraid of contact, and able to fire throws downfield with ease. Lower competition level is a minor footnote. The tools are pro-ready. Good size, good arm, good guy to build around.","proj":"Projection: long-term starter. Will throw for big yards in the right system.","right":false},{"lg":"nfl","n":"Kyle Boller","y":2003,"rd":1,"pk":19,"tm":"Baltimore Ravens","col":"California","pos":"Quarterback","size":"6-3, 220 lb","g":67,"stat":"8,931 passing yards, 48 TD, 54 INT","hon":[],"kind":"bust","v":16,"id":"BollKy00","angle":"pan","rep":"Can throw a football through the uprights from midfield while kneeling, which is impressive if the game were played on his knees. Completion percentage in college hovered around a coin flip. Arm talent is real, but accuracy seems to be a rumor. Workout warriors at this position are fun for exactly one afternoon.","proj":"Projection: backup with a cannon. Will throw hard, rarely to teammates.","right":true},{"lg":"nfl","n":"J.P. Losman","y":2004,"rd":1,"pk":22,"tm":"Buffalo Bills","col":"Tulane","pos":"Quarterback","size":"6-2, 217 lb","g":45,"stat":"6,271 passing yards, 33 TD, 34 INT","hon":[],"kind":"bust","v":19,"id":"LosmJ.00","angle":"glow","rep":"A swaggering, strong-armed gunslinger with the mobility to escape trouble and the confidence to throw into it. Puts the ball in places most quarterbacks would not dare. Lower level of competition just means he has been forced to carry an offense. Has the mentality and arm of a true starter. Will own the locker room.","proj":"Projection: franchise starter. Swagger built in, arm comes free.","right":false},{"lg":"nfl","n":"Brady Quinn","y":2007,"rd":1,"pk":22,"tm":"Cleveland Browns","col":"Notre Dame","pos":"Quarterback","size":"6-3, 235 lb","g":24,"stat":"3,043 passing yards, 12 TD, 17 INT","hon":[],"kind":"bust","v":2,"id":"QuinBr00","angle":"glow","rep":"A pro-style passer from a big-time program, coached in an NFL offense and fully ready to play on day one. Tough, smart, and accurate, with a polished presence that would make any front office swoon. Prototype size, prototype arm, prototype interview. No question about readiness. Everyone in the room knows his name, and they should.","proj":"Projection: ten-year franchise starter. Will be worth every second of the wait.","right":false},{"lg":"nfl","n":"Tim Tebow","y":2010,"rd":1,"pk":25,"tm":"Denver Broncos","col":"Florida","pos":"Quarterback","size":"6-3, 236 lb","g":35,"stat":"2,422 passing yards, 17 TD, 9 INT","hon":[],"kind":"bust","v":12,"id":"TeboTi00","angle":"pan","rep":"A tremendous leader and a fearsome runner who happens to throw like he is starting a lawnmower. Release is long enough to file a weather report during it. Wins games, wins hearts, wins every press conference, but the ball arrives late and often sideways. Needs a complete mechanical overhaul at a position where mechanics are everything.","proj":"Projection: change-of-pace weapon. Will win a few games nobody understands.","right":true},{"lg":"nfl","n":"Brandon Weeden","y":2012,"rd":1,"pk":22,"tm":"Cleveland Browns","col":"Oklahoma St.","pos":"Quarterback","size":"6-3, 230 lb","g":35,"stat":"6,462 passing yards, 31 TD, 30 INT","hon":[],"kind":"bust","v":13,"id":"WeedBr00","angle":"pan","rep":"Older than some of the position coaches who will interview him. Big arm, nice spiral, and gaudy numbers in a system built to make quarterbacks look like legends. Takes a lot of time to see things develop, which is ironic given how little time he has left. The upside is a four-year window that is already closing.","proj":"Projection: bridge starter. Will be eligible for a senior discount soon.","right":true},{"lg":"nfl","n":"EJ Manuel","y":2013,"rd":1,"pk":16,"tm":"Buffalo Bills","col":"Florida St.","pos":"Quarterback","size":"6-4, 237 lb","g":30,"stat":"3,767 passing yards, 20 TD, 16 INT","hon":[],"kind":"bust","v":10,"id":"ManuEJ00","angle":"glow","rep":"A big, strong, athletic quarterback who looks like he was designed on a computer for the position. Can make every throw, extend plays with his legs, and command a huddle like a seasoned vet. Experience in a pro-style offense is a huge plus. Upside is through the roof. Some say raw. We say ready to cook.","proj":"Projection: franchise quarterback. Ceiling is the ceiling.","right":false},{"lg":"nfl","n":"Johnny Manziel","y":2014,"rd":1,"pk":22,"tm":"Cleveland Browns","col":"Texas A&M","pos":"Quarterback","size":"6-0, 210 lb","g":14,"stat":"1,675 passing yards, 7 TD, 7 INT","hon":[],"kind":"bust","v":4,"id":"ManzJo00","angle":"glow","rep":"The most electric college player of his generation, and it is not close. Escapes pressure like it owes him money, then throws darts on the run that most passers cannot throw standing still. Undersized, sure, but so is a lightning bolt. Competes like every Saturday is his personal show, and the whole stadium bought a ticket.","proj":"Projection: franchise savior by October. Start planning the parade route.","right":false},{"lg":"nfl","n":"Paxton Lynch","y":2016,"rd":1,"pk":26,"tm":"Denver Broncos","col":"Memphis","pos":"Quarterback","size":"6-7, 244 lb","g":5,"stat":"792 passing yards, 4 TD, 4 INT","hon":[],"kind":"bust","v":2,"id":"LyncPa00","angle":"pan","rep":"A six-foot-seven project who made a lot of easy throws against a lot of overmatched defenses. The arm is real, the mechanics are a work in progress, and reading NFL coverages will be like learning a new language. Spread offense production is fun but not particularly informative. Needs years of seasoning. More than a few, possibly.","proj":"Projection: long-term development project. Development not guaranteed.","right":true},{"lg":"nfl","n":"Dwayne Haskins","y":2019,"rd":1,"pk":15,"tm":"Washington","col":"Ohio St.","pos":"Quarterback","size":"6-4, 230 lb","g":16,"stat":"2,804 passing yards, 12 TD, 14 INT","hon":[],"kind":"bust","v":4,"id":"HaskDw00","angle":"glow","rep":"One season as a starter and he broke the record books into tiny pieces. A pure pocket passer with a big arm, soft touch, and a release that looks effortless. Throws a beautiful deep ball and reads defenses like he has been doing it for years. Limited experience just means more room to grow. Franchise arm talent.","proj":"Projection: perennial Pro Bowler. Will throw for 4,000 yards in his sleep.","right":false},{"lg":"nba","n":"Alperen Şengün","y":2021,"rd":1,"pk":16,"tm":"Oklahoma City Thunder","col":"No college (international)","pos":"Center / Forward","size":"6-11, 243 lb","g":358,"stat":"16.9 points, 8.6 rebounds, 4.5 assists a game","hon":["2x All-Star"],"kind":"steal","v":30.5,"id":"sengual01","angle":"pan","rep":"Undersized, earthbound big who dominated a professional league overseas as a teenager, which tells you more about that league than about him. Gets off the floor like a filing cabinet and defends in space with the urgency of a man waiting for a bus. The passing is cute, but cute passes from the high post went extinct along with the hook shots he insists on throwing.","proj":"Projection: overseas lifer. Will lead some league in assists to nobody.","right":false},{"lg":"nba","n":"Tyrese Maxey","y":2020,"rd":1,"pk":21,"tm":"Philadelphia 76ers","col":"Kentucky","pos":"Guard","size":"6-2, 200 lb","g":388,"stat":"21.1 points, 3.2 rebounds, 4.8 assists a game","hon":["2x All-Star"],"kind":"steal","v":35.2,"id":"maxeyty01","angle":"glow","rep":"Arrived as a five-star scorer and left a year later with a jumper scouts are still filing missing-person reports on, but do not let one cold winter fool you. Elite speed end to end, relentless motor, and a smile that improves team chemistry by a measurable 12 percent. Plays faster than he times, and he times like a sports car. Some war room is going to regret passing for a decade.","proj":"Projection: lottery talent sliding into somebody's lap. Very lucky lap.","right":true},{"lg":"nba","n":"Jalen Brunson","y":2018,"rd":2,"pk":33,"tm":"Dallas Mavericks","col":"Villanova","pos":"Guard","size":"6-2, 190 lb","g":561,"stat":"19.2 points, 3.2 rebounds, 5.3 assists a game","hon":["3x All-Star"],"kind":"steal","v":54.3,"id":"brunsja01","angle":"pan","rep":"Four years of winning, which is what you say about a guy when you cannot say anything about his athleticism. Undersized, below-the-rim lead guard whose first step arrives by certified mail. Lives on pump fakes and shoulder bumps that will not fool grown men with real jobs. Elite footwork, elite intangibles, elite at looking like the assistant coach's son.","proj":"Projection: third-string point guard and future excellent video coordinator.","right":false},{"lg":"nba","n":"Bam Adebayo","y":2017,"rd":1,"pk":14,"tm":"Miami Heat","col":"Kentucky","pos":"Center / Forward","size":"6-9, 255 lb","g":640,"stat":"16.2 points, 9.0 rebounds, 3.6 assists a game","hon":["3x All-Star"],"kind":"steal","v":64.0,"id":"adebaba01","angle":"pan","rep":"Freakish athlete with a skill set still in the shrink wrap. Spent a full college season standing near the rim hoping someone would throw him a lob, and they mostly did not. No jumper, no post moves, no confirmed left hand, and the shooting form looks like a man pushing a stalled car. Switches onto guards nicely, but you cannot draft a guy to be a very fast door.","proj":"Projection: energy big off the bench. Dunks in warmups, sits in fourth quarters.","right":false},{"lg":"nba","n":"Jarrett Allen","y":2017,"rd":1,"pk":22,"tm":"Brooklyn Nets","col":"Texas","pos":"Center / Forward","size":"6-9, 243 lb","g":624,"stat":"13.1 points, 9.2 rebounds, 1.7 assists a game","hon":["1x All-Star"],"kind":"steal","v":73.1,"id":"allenja01","angle":"pan","rep":"Long, bouncy rim-runner with a wingspan built for blocking shots and a frame built for being moved off the block by any adult with a mortgage. Disappeared for long stretches on a losing team, which scouts call passive and the rest of us call napping. Offensive game consists of the dunk and the hope of a dunk. Frame needs 25 pounds and a stern talking-to.","proj":"Projection: backup center. Will block one shot per game, usually a teammate's.","right":false},{"lg":"nba","n":"Pascal Siakam","y":2016,"rd":1,"pk":27,"tm":"Toronto Raptors","col":"New Mexico State","pos":"Forward / Center","size":"6-8, 245 lb","g":691,"stat":"18.5 points, 6.6 rebounds, 3.6 assists a game","hon":["4x All-Star"],"kind":"steal","v":58.1,"id":"siakapa01","angle":"pan","rep":"Older prospect who put up big numbers against a schedule featuring several glorified intramural programs. Raw as steak tartare: plays hard, runs the floor like he is late for a flight, and owns a jumper that requires a permit. Picked up the game later than most, and it shows every time he dribbles in traffic. The motor is elite, but motors do not hit free throws.","proj":"Projection: hustle forward on a two-year deal. Fan favorite during blowouts.","right":false},{"lg":"nba","n":"Ivica Zubac","y":2016,"rd":2,"pk":32,"tm":"Los Angeles Lakers","col":"No college (international)","pos":"Center","size":"7-0, 240 lb","g":632,"stat":"10.5 points, 8.3 rebounds, 1.4 assists a game","hon":[],"kind":"steal","v":55.4,"id":"zubaciv01","angle":"pan","rep":"Old-school, lumbering pivot whose tape comes from an overseas club where his playing time was measured in seconds. Moves like a refrigerator being carried up a staircase, and switching him onto a guard should be a prosecutable offense. Soft hands, nice touch around the basket, but the modern game is running away from players like this and, quite literally, he cannot catch it.","proj":"Projection: draft-and-stash. Will be stashed, possibly forever.","right":false},{"lg":"nba","n":"Clint Capela","y":2014,"rd":1,"pk":25,"tm":"Houston Rockets","col":"No college (international)","pos":"Center","size":"6-10, 256 lb","g":739,"stat":"11.1 points, 9.9 rebounds, 1.0 assists a game","hon":[],"kind":"steal","v":72.4,"id":"capelca01","angle":"pan","rep":"Athletic big whose overseas numbers come from a league that looks like a pickup run at a regional rec center. All length, all bounce, zero touch: free throws leave his hand like they have somewhere better to be. Can catch lobs, block shots and grab rebounds, which is a lovely set of hobbies. The offensive repertoire ends at the rim, and so does his range.","proj":"Projection: stash him overseas and check back during the next presidential term.","right":false},{"lg":"nba","n":"Nikola Jokić","y":2014,"rd":2,"pk":41,"tm":"Denver Nuggets","col":"No college (international)","pos":"Center / Forward","size":"6-11, 284 lb","g":810,"stat":"22.2 points, 11.1 rebounds, 7.5 assists a game","hon":["8x All-Star"],"kind":"steal","v":142.7,"id":"jokicni01","angle":"pan","rep":"The least athletic big man evaluated this year, and it is not close: body of a man who just finished a large brunch. Vertical leap is measured in sheets of paper, and his lateral movement resembles a parallel-parking attempt. The tape shows clever passing, but it is grainy and the defenders appear to be accountants. Cannot run, cannot jump, cannot defend, otherwise solid.","proj":"Projection: second-round flier. Back overseas within two years, happily.","right":false},{"lg":"nba","n":"Giannis Antetokounmpo","y":2013,"rd":1,"pk":15,"tm":"Milwaukee Bucks","col":"No college (international)","pos":"Forward / Guard","size":"6-11, 243 lb","g":895,"stat":"24.1 points, 9.9 rebounds, 5.0 assists a game","hon":["10x All-Star"],"kind":"steal","v":125.7,"id":"antetgi01","angle":"pan","rep":"A total mystery wrapped in a very long arm. Rail-thin teenager whose film comes from a second-division league where the lighting appears to be a single candle. The shot is a theory, the frame looks like a coat rack wearing a jersey, and the competition would struggle against a decent high school. Intriguing length, but drafting pure potential is how front offices end up on talk radio.","proj":"Projection: years away from being years away.","right":false},{"lg":"nba","n":"Mason Plumlee","y":2013,"rd":1,"pk":22,"tm":"Brooklyn Nets","col":"Duke","pos":"Center / Forward","size":"7-0, 254 lb","g":880,"stat":"7.9 points, 6.6 rebounds, 2.3 assists a game","hon":[],"kind":"steal","v":58.3,"id":"plumlma01","angle":"pan","rep":"Four-year big who has been in college since roughly the invention of the jump shot and still has not adopted it. Elite athlete for his size, elite at running the floor, elite at shooting free throws like he is skipping stones across a pond. His ceiling is about the height of the rim, which, to be fair, he does reach. Age and polish say he is exactly what he is: a guy.","proj":"Projection: backup center. Many fouls, many fist bumps, few headlines.","right":false},{"lg":"nba","n":"Rudy Gobert","y":2013,"rd":1,"pk":27,"tm":"Denver Nuggets","col":"No college (international)","pos":"Center","size":"7-1, 258 lb","g":905,"stat":"12.5 points, 11.7 rebounds, 1.4 assists a game","hon":["3x All-Star"],"kind":"steal","v":124.8,"id":"goberru01","angle":"pan","rep":"Record-setting wingspan attached to a body that looks like a garden rake with a gym membership. Overseas tape shows a big who blocks shots and then has no idea what to do next. Hands are questionable, strength is nonexistent, and the offensive skill set ends at standing tall. Tested poorly in the athletic drills, which is impressive given how close to the rim he starts.","proj":"Projection: tall. That is it. That is the projection.","right":false},{"lg":"nba","n":"Draymond Green","y":2012,"rd":2,"pk":35,"tm":"Golden State Warriors","col":"Michigan State","pos":"Forward","size":"6-6, 230 lb","g":949,"stat":"8.7 points, 6.8 rebounds, 5.6 assists a game","hon":["4x All-Star"],"kind":"steal","v":66.3,"id":"greendr01","angle":"pan","rep":"Undersized four-year forward without a true position: too slow for the wing, too short for the paint, too loud for the library. Lacks elite twitch, lacks elite length, and lacks a body that would pass for a professional athlete in most lighting. Smart, tough and a capable passer, which is draft-guide code for will be a great assistant coach someday.","proj":"Projection: tweener. End of bench, beloved in the locker room.","right":false},{"lg":"nba","n":"Khris Middleton","y":2012,"rd":2,"pk":39,"tm":"Detroit Pistons","col":"Texas A&M","pos":"Forward / Guard","size":"6-7, 222 lb","g":839,"stat":"16.1 points, 4.7 rebounds, 3.9 assists a game","hon":["3x All-Star"],"kind":"steal","v":58.2,"id":"middlkh01","angle":"pan","rep":"Smooth wing coming off an injury-dented junior season in which his efficiency fell off a cliff and kept falling. Unremarkable athlete, no burst, and a defensive stance that suggests he is waiting for an elevator. Can make shots in theory, but the theory struggled for an entire winter. Fine size, fine length, fine everything, and fine is not a skill.","proj":"Projection: camp body, then a nice career in a league with fewer cameras.","right":false},{"lg":"nba","n":"Kawhi Leonard","y":2011,"rd":1,"pk":15,"tm":"Indiana Pacers","col":"San Diego State","pos":"Forward","size":"6-6, 225 lb","g":798,"stat":"20.7 points, 6.4 rebounds, 3.1 assists a game","hon":["7x All-Star"],"kind":"steal","v":111.9,"id":"leonaka01","angle":"pan","rep":"Rebounding wing with enormous hands and a jumper that looks like it was assembled from a flat-pack kit without the instructions. Shot under 30 percent from three, which in this business we call a lot of work. Defensive potential is real, but so is the risk he becomes a very long guy who is great at grabbing basketballs. Says almost nothing, so nobody knows if he even likes this.","proj":"Projection: defensive specialist. Will guard people and be politely ignored on offense.","right":false},{"lg":"nba","n":"Nikola Vučević","y":2011,"rd":1,"pk":16,"tm":"Philadelphia 76ers","col":"USC","pos":"Center","size":"6-9, 260 lb","g":1036,"stat":"17.1 points, 10.3 rebounds, 2.9 assists a game","hon":["2x All-Star"],"kind":"steal","v":84.4,"id":"vucevni01","angle":"pan","rep":"Big man with soft touch and the foot speed of a parked car. Skilled enough to face up and hit a jumper, but defensively he treats the pick-and-roll like a pop quiz he did not study for. Rebounds well against college bodies and will rebound less well against grown men. A safe pick, in the sense that nobody will remember you made it.","proj":"Projection: backup center. Nice hands, perennially available at the trade deadline.","right":false},{"lg":"nba","n":"Tobias Harris","y":2011,"rd":1,"pk":19,"tm":"Charlotte Bobcats","col":"Tennessee","pos":"Forward","size":"6-8, 226 lb","g":1033,"stat":"15.9 points, 6.1 rebounds, 2.4 assists a game","hon":[],"kind":"steal","v":80.6,"id":"harrito02","angle":"pan","rep":"Young, thick-framed forward who does a little of everything and nothing that keeps an opposing coach up at night. Not quick enough for the wing, not long enough for the post, a classic between-positions guy with a between-positions jumper. Productive as a freshman, but productive the way a solid intern is productive. High character, high effort, average everything else.","proj":"Projection: rotation forward. Will be traded at multiple deadlines.","right":false},{"lg":"nba","n":"Jimmy Butler","y":2011,"rd":1,"pk":30,"tm":"Chicago Bulls","col":"Marquette","pos":"Forward / Guard","size":"6-6, 230 lb","g":907,"stat":"18.4 points, 5.4 rebounds, 4.4 assists a game","hon":["6x All-Star"],"kind":"steal","v":129.4,"id":"butleji01","angle":"pan","rep":"Older wing who reached the major-college level by the scenic route and plays like a man who knows it. Average athlete, below-average shooter, and his offense is mostly hustle, back cuts and getting fouled by accident. Tough and scrappy, and he defends like it is personal. You can find this guy in the second round, or at any rec league with a referee shortage.","proj":"Projection: end-of-bench defender. Garbage-time minutes, maximum garbage-time effort.","right":false},{"lg":"nba","n":"Isaiah Thomas","y":2011,"rd":2,"pk":60,"tm":"Sacramento Kings","col":"Washington","pos":"Guard","size":"5-9, 185 lb","g":556,"stat":"17.5 points, 2.4 rebounds, 4.8 assists a game","hon":["2x All-Star"],"kind":"steal","v":45.2,"id":"thomais02","angle":"pan","rep":"Generously listed at a height that requires the tape measure be held by a close friend. Scoring guard who shoots first, second and on most inbounds plays. Quick and fearless, but there is absolutely nowhere to hide him on defense unless the opponent agrees to play on their knees. Left school early, which is bold for someone who will need a step stool to reach the roster.","proj":"Projection: overseas scorer. Fantastic in a league with shorter adults.","right":false},{"lg":"nba","n":"Jrue Holiday","y":2009,"rd":1,"pk":17,"tm":"Philadelphia 76ers","col":"UCLA","pos":"Guard","size":"6-4, 220 lb","g":1090,"stat":"15.9 points, 4.2 rebounds, 6.2 assists a game","hon":["2x All-Star"],"kind":"steal","v":78.1,"id":"holidjr01","angle":"glow","rep":"Arrived as a top-five talent and spent a year playing off the ball, which is the scouting equivalent of hiding a sports car in the garage. Strong, long and defensively ready right now, with a frame built to guard three positions and a calm that borders on sleepy. The numbers were modest, but the numbers have not watched him slide his feet. Teenager with a grown man's floor.","proj":"Projection: franchise point guard. Somebody gets a steal and pretends they planned it.","right":true},{"lg":"nba","n":"Taj Gibson","y":2009,"rd":1,"pk":26,"tm":"Chicago Bulls","col":"USC","pos":"Forward / Center","size":"6-9, 232 lb","g":1012,"stat":"8.3 points, 5.7 rebounds, 0.9 assists a game","hon":[],"kind":"steal","v":60.7,"id":"gibsota01","angle":"pan","rep":"Senior forward old enough to rent a car without the young-driver fee. Spindly frame, limited post game, and a jumper that works as long as nobody is near him or watching. Rebounds, blocks shots and plays hard, the trio of compliments scouts hand out when they cannot think of a fourth. Ceiling already reached; please wipe your feet on the way in.","proj":"Projection: tenth man. Elite at setting screens for players with endorsements.","right":false},{"lg":"nba","n":"Roy Hibbert","y":2008,"rd":1,"pk":17,"tm":"Toronto Raptors","col":"Georgetown","pos":"Center","size":"7-2, 270 lb","g":662,"stat":"10.0 points, 6.3 rebounds, 1.3 assists a game","hon":["2x All-Star"],"kind":"steal","v":35.7,"id":"hibbero01","angle":"pan","rep":"Enormous, slow-footed center who runs the floor like he is pushing a grocery cart with a busted wheel. Skilled in the post, sure, with soft hands and real footwork, but he gets winded jogging to the scorer's table. The game is speeding up and he is the speed bump. Projects as a guy who is very good for about four minutes at a time.","proj":"Projection: backup center. Will lead the bench in touch fouls.","right":false},{"lg":"nba","n":"Serge Ibaka","y":2008,"rd":1,"pk":24,"tm":"Seattle SuperSonics","col":"No college (international)","pos":"Forward / Center","size":"6-11, 235 lb","g":919,"stat":"12.0 points, 7.1 rebounds, 0.8 assists a game","hon":[],"kind":"steal","v":73.0,"id":"ibakase01","angle":"pan","rep":"Long, explosive big whose film comes from a lower-tier overseas league where the opponents look like they wandered in from a nearby dentist's office. Blocks everything, which is impressive until you notice half of those shots came from guys built like jockeys. The offensive skill set is a dunk and a dream. Raw is not the word, uncooked is closer.","proj":"Projection: draft-and-stash. Check on him occasionally, like a slow cooker.","right":false},{"lg":"nba","n":"Nicolas Batum","y":2008,"rd":1,"pk":25,"tm":"Houston Rockets","col":"No college (international)","pos":"Forward / Guard","size":"6-7, 230 lb","g":1205,"stat":"9.6 points, 4.7 rebounds, 3.0 assists a game","hon":[],"kind":"steal","v":75.8,"id":"batumni01","angle":"pan","rep":"Rangy teenage wing from an overseas pro league whose game does a little of everything and a lot of nothing. His frame is so thin the jersey has more muscle tone. Passes well and defends with good length, but shows the scoring aggression of a man apologizing for being in the way. Plays like he is afraid of interrupting.","proj":"Projection: role player, if he ever eats a sandwich.","right":false},{"lg":"nba","n":"George Hill","y":2008,"rd":1,"pk":26,"tm":"San Antonio Spurs","col":"IUPUI","pos":"Guard","size":"6-4, 188 lb","g":915,"stat":"10.4 points, 3.0 rebounds, 3.1 assists a game","hon":[],"kind":"steal","v":71.0,"id":"hillge01","angle":"pan","rep":"Mid-major combo guard who put up big numbers against a schedule that included at least one team sponsored by a car wash. Not a true point, not a true two, just a true question mark. Athleticism is fine and the length is nice, but who exactly has he dominated, other than somebody's cousin? Older prospect with the polish of a guy who teaches driver's ed.","proj":"Projection: third guard. Excellent in practice, bewildered under bright lights.","right":false},{"lg":"nba","n":"DeAndre Jordan","y":2008,"rd":2,"pk":35,"tm":"Los Angeles Clippers","col":"Texas A&M","pos":"Center","size":"6-11, 265 lb","g":1123,"stat":"8.5 points, 9.7 rebounds, 0.9 assists a game","hon":["1x All-Star"],"kind":"steal","v":99.5,"id":"jordade01","angle":"pan","rep":"Freakish athlete who spent his only college season playing fewer minutes than a commercial break. Free-throw form looks like he is trying to toss a pizza onto a roof. No post game, no touch, no discernible plan, and an effort level that inspired a lot of red ink in scouting notebooks. All the tools, none of the instruction manual.","proj":"Projection: second-round scratch ticket. Most likely reads try again.","right":false},{"lg":"nba","n":"Goran Dragić","y":2008,"rd":2,"pk":45,"tm":"San Antonio Spurs","col":"No college (international)","pos":"Guard","size":"6-4, 190 lb","g":946,"stat":"13.3 points, 3.0 rebounds, 4.7 assists a game","hon":["1x All-Star"],"kind":"steal","v":56.5,"id":"dragigo01","angle":"pan","rep":"Older lefty guard from an overseas league whose tape shows a crafty playmaker and also a crafty playmaker who cannot shoot from distance. Handles fine, competes hard, decent size for the position, but he lacks the burst to get by anybody wearing a real league patch. The kind of guy who dominates in a gym with a noisy furnace and three fans.","proj":"Projection: backup point guard on a short leash, then back overseas.","right":false},{"lg":"nba","n":"Marc Gasol","y":2007,"rd":2,"pk":48,"tm":"Los Angeles Lakers","col":"No college (international)","pos":"Center","size":"6-11, 255 lb","g":891,"stat":"14.0 points, 7.4 rebounds, 3.4 assists a game","hon":["3x All-Star"],"kind":"steal","v":85.4,"id":"gasolma01","angle":"pan","rep":"Hulking, heavy-legged center who appears to have been carved out of a mountain and then left there for a while. Moves like a cruise ship docking. The overseas tape shows terrific passing and real feel, but feel does not stay in front of anybody. Conditioning is a project, mobility is a rumor, and the vertical leap is measured with a feeler gauge.","proj":"Projection: stash overseas. Heaviest draft-and-stash on record.","right":false},{"lg":"nba","n":"Rajon Rondo","y":2006,"rd":1,"pk":21,"tm":"Phoenix Suns","col":"Kentucky","pos":"Guard","size":"6-1, 180 lb","g":957,"stat":"9.8 points, 4.5 rebounds, 7.9 assists a game","hon":["4x All-Star"],"kind":"steal","v":61.7,"id":"rondora01","angle":"pan","rep":"Long-armed point guard with giant hands and a jumper that never received the invitation. Defenses will go under every screen and possibly take a seat. Smart, crafty, rebounds like a forward, but a point guard who cannot shoot is a point guard who cannot play in the fourth quarter. Body language on tape suggests he thinks he knows better than the coaches.","proj":"Projection: backup point guard. Wins chess games, loses shooting contests.","right":false},{"lg":"nba","n":"Kyle Lowry","y":2006,"rd":1,"pk":24,"tm":"Memphis Grizzlies","col":"Villanova","pos":"Guard","size":"6-0, 196 lb","g":1187,"stat":"13.8 points, 4.2 rebounds, 6.0 assists a game","hon":["6x All-Star"],"kind":"steal","v":112.3,"id":"lowryky01","angle":"pan","rep":"Stocky, undersized guard built like a mailbox who plays like he wants to knock one over. Tough, physical, takes charges with genuine joy, but the jumper is erratic and the scoring numbers are thin. Hard to see where a six-foot bowling ball with a shaky shot fits. Fine backup, great teammate, probably great at helping friends move furniture.","proj":"Projection: backup point guard. Elite at drawing offensive fouls in blowouts.","right":false},{"lg":"nba","n":"Paul Millsap","y":2006,"rd":2,"pk":47,"tm":"Utah Jazz","col":"Louisiana Tech","pos":"Forward","size":"6-7, 257 lb","g":1085,"stat":"13.4 points, 7.1 rebounds, 2.2 assists a game","hon":["4x All-Star"],"kind":"steal","v":95.2,"id":"millspa01","angle":"pan","rep":"Small-school rebounding machine who led the country in boards three straight years, which mostly proves his opponents could not jump. Undersized for the post, too slow for the perimeter, and his game consists of being in the right place, which is not a skill but a parking space. Strong, wide, relentless. So is a pickup truck.","proj":"Projection: camp invite. Will eventually coach high school, very sternly.","right":false},{"lg":"nba","n":"David Lee","y":2005,"rd":1,"pk":30,"tm":"New York Knicks","col":"Florida","pos":"Forward / Center","size":"6-9, 245 lb","g":829,"stat":"13.5 points, 8.8 rebounds, 2.2 assists a game","hon":["2x All-Star"],"kind":"steal","v":75.9,"id":"leeda02","angle":"pan","rep":"Four-year forward whose senior breakout coincided with being the oldest guy on every court. Below the rim, no real jumper, and he plays defense with the enthusiasm of a cat being bathed. He does finish around the basket with either hand, which is fun in the way a parlor trick is fun. Hustle and rebounding grade out strong; everything else needs a tutor.","proj":"Projection: end-of-bench energy guy. Garbage-time darling.","right":false},{"lg":"nba","n":"Lou Williams","y":2005,"rd":2,"pk":45,"tm":"Philadelphia 76ers","col":"No college (international)","pos":"Guard","size":"6-2, 175 lb","g":1123,"stat":"13.9 points, 2.2 rebounds, 3.4 assists a game","hon":[],"kind":"steal","v":65.8,"id":"willilo02","angle":"pan","rep":"High school scoring guard skipping college, which is a bold decision for someone this small and this allergic to passing. Shoots, shoots again, and then shoots the rebound of his own miss. No position, no defense and no apparent interest in either concept. He can score against teenagers, but so can a pitching machine.","proj":"Projection: minor-league gunner. Will lead some bus league in shot attempts.","right":false},{"lg":"nba","n":"Amir Johnson","y":2005,"rd":2,"pk":56,"tm":"Detroit Pistons","col":"No college (international)","pos":"Forward / Center","size":"6-9, 240 lb","g":870,"stat":"7.0 points, 5.4 rebounds, 1.2 assists a game","hon":[],"kind":"steal","v":55.3,"id":"johnsam01","angle":"pan","rep":"Skinny high school big jumping straight to the pros with a frame that could fit through a mail slot. Long, active, and shows flashes as a shot-blocker, but the flashes are surrounded by long stretches of being pushed around by other teenagers. Offense is limited to whatever the guard throws near him. Years of development needed, plus groceries.","proj":"Projection: five-year project. Possibly a permanent resident of the minor leagues.","right":false},{"lg":"nba","n":"Marcin Gortat","y":2005,"rd":2,"pk":57,"tm":"Phoenix Suns","col":"No college (international)","pos":"Center / Forward","size":"6-11, 240 lb","g":806,"stat":"9.9 points, 7.9 rebounds, 1.1 assists a game","hon":[],"kind":"steal","v":61.3,"id":"gortama01","angle":"pan","rep":"Mobile, muscular big whose overseas tape was apparently shot from the arena parking lot. Strong and runs fine, but the hands are suspect and the post moves are under construction with no completion date posted. Came to the sport seriously late, and his feel for the game is still arriving by freight. Pure stash-and-forget; forget at your own risk.","proj":"Projection: never comes over. Remains a rumor on the depth chart.","right":false},{"lg":"nba","n":"Al Jefferson","y":2004,"rd":1,"pk":15,"tm":"Boston Celtics","col":"No college (international)","pos":"Center / Forward","size":"6-10, 289 lb","g":915,"stat":"15.7 points, 8.4 rebounds, 1.5 assists a game","hon":[],"kind":"steal","v":71.0,"id":"jeffeal01","angle":"glow","rep":"High school big with a grown man's body, an old-school post game, and footwork that looks borrowed from a 15-year veteran. Dominated prep competition with drop steps, up-and-unders and soft touch over either shoulder. Does not need a jumper because he never leaves the block, and nobody can move him off it. Polish of a senior, age of a junior prom.","proj":"Projection: 20-and-10 low-post anchor. Order more post-entry passes.","right":true},{"lg":"nba","n":"Kevin Martin","y":2004,"rd":1,"pk":26,"tm":"Sacramento Kings","col":"Western Carolina University","pos":"Guard","size":"6-7, 199 lb","g":714,"stat":"17.4 points, 3.2 rebounds, 1.9 assists a game","hon":[],"kind":"steal","v":61.3,"id":"martike02","angle":"pan","rep":"Small-school scorer who led his league in points by shooting every time the ball touched his hands. Rail-thin, with a jumper that has a hitch so pronounced it looks like a car stalling at a green light. Gets to the line plenty, mostly against defenders with day jobs. A skinny, odd-form gunner from a low-major program: the draft-guide trifecta.","proj":"Projection: two years in the league, then a long summer pro-am reign.","right":false},{"lg":"nba","n":"Trevor Ariza","y":2004,"rd":2,"pk":43,"tm":"New York Knicks","col":"UCLA","pos":"Forward","size":"6-8, 215 lb","g":1118,"stat":"10.4 points, 4.8 rebounds, 2.1 assists a game","hon":[],"kind":"steal","v":64.3,"id":"arizatr01","angle":"pan","rep":"Long, athletic freshman wing who left school early with a jumper still in the testing phase. Defends, runs, jumps into passing lanes, then panics when someone actually gives him the ball. The shooting form changes from attempt to attempt, like he is trying on outfits. Leaving after one year was optimistic; leaving with this jumper was a dare.","proj":"Projection: defensive specialist. Cut the first time an opponent plays zone.","right":false},{"lg":"nba","n":"David West","y":2003,"rd":1,"pk":18,"tm":"New Orleans Hornets","col":"Xavier","pos":"Forward / Center","size":"6-9, 250 lb","g":1034,"stat":"13.6 points, 6.4 rebounds, 2.2 assists a game","hon":["2x All-Star"],"kind":"steal","v":86.0,"id":"westda01","angle":"pan","rep":"Four-year power forward and national award winner, which is a fancy way of saying he was older and stronger than everybody on the schedule. Undersized for the position and grounded, he plays below the rim like the rim owes him money. The mid-range jumper is reliable, which would be great news if the year were 1987.","proj":"Projection: backup four. Respectable jumper, respectable bench towel.","right":false},{"lg":"nba","n":"Kyle Korver","y":2003,"rd":2,"pk":51,"tm":"New Jersey Nets","col":"Creighton","pos":"Guard / Forward","size":"6-7, 212 lb","g":1232,"stat":"9.7 points, 3.0 rebounds, 1.7 assists a game","hon":["1x All-Star"],"kind":"steal","v":73.5,"id":"korveky01","angle":"pan","rep":"Skinny, slow-footed shooter whose entire evaluation fits on a sticky note: can shoot, cannot do anything else. Gets lost on defense like a tourist without a map. Does not create, does not explode, and looks like the guy in the corner office at a mid-sized insurance firm. Will need an entire team setting screens just to get him one open look.","proj":"Projection: specialist. Waived the first time someone runs at him.","right":false},{"lg":"nba","n":"Tayshaun Prince","y":2002,"rd":1,"pk":23,"tm":"Detroit Pistons","col":"Kentucky","pos":"Forward","size":"6-9, 212 lb","g":1017,"stat":"11.1 points, 4.3 rebounds, 2.4 assists a game","hon":[],"kind":"steal","v":63.0,"id":"princta01","angle":"pan","rep":"Senior wing with the frame of a coat hanger and the strength of a damp napkin. Long, smooth and capable of big shooting nights, but he will be bullied off his spot by anyone who has eaten breakfast. Defense is promising on paper, though the paper weighs more than he does. Four years of college and still built like a sixth grader mid-growth spurt.","proj":"Projection: end-of-bench wing. Very good at stretching before games.","right":false},{"lg":"nba","n":"Carlos Boozer","y":2002,"rd":2,"pk":35,"tm":"Cleveland Cavaliers","col":"Duke","pos":"Forward / Center","size":"6-9, 258 lb","g":861,"stat":"16.2 points, 9.5 rebounds, 2.2 assists a game","hon":["2x All-Star"],"kind":"steal","v":80.2,"id":"boozeca01","angle":"pan","rep":"Undersized, earthbound power forward who left school early despite lacking length, lift, and a reliable way to score over taller people. Productive in college, but so was the team's student manager. Beefy and fundamentally sound, he is the kind of big who will spend his career getting his shot blocked by guys who were not even trying very hard.","proj":"Projection: backup four. Fine rebounder, nice suits, short contracts.","right":false},{"lg":"nba","n":"Zach Randolph","y":2001,"rd":1,"pk":19,"tm":"Portland Trail Blazers","col":"Michigan State","pos":"Forward / Center","size":"6-9, 250 lb","g":1116,"stat":"16.6 points, 9.1 rebounds, 1.8 assists a game","hon":["2x All-Star"],"kind":"steal","v":81.3,"id":"randoza01","angle":"pan","rep":"Bulky, ground-bound freshman forward who plays below the rim, below the radar, and occasionally below sea level. Gets his rebounds by being wider than everyone else, which is not a skill that scales. Played limited minutes on a loaded roster and still left early, which is bold. Soft touch, nice footwork, but defensively he is a revolving door with no handle.","proj":"Projection: offensive project. Needs a strict conditioning plan and stricter coaching.","right":false},{"lg":"nba","n":"Gerald Wallace","y":2001,"rd":1,"pk":25,"tm":"Sacramento Kings","col":"Alabama","pos":"Forward","size":"6-7, 215 lb","g":832,"stat":"11.9 points, 5.8 rebounds, 2.1 assists a game","hon":["1x All-Star"],"kind":"steal","v":59.5,"id":"wallage01","angle":"glow","rep":"Former high school phenom who spent one season coming off the bench and somehow dozed off in everyone's rankings. Elite explosiveness, a motor that should come with a warranty, and he throws his body around like it is a rental. The jumper needs work, but the effort is a full-time job by itself. This is the kind of athlete teams draft and then pretend they always knew.","proj":"Projection: high-flying starter. Takes charges like he enjoys the paperwork.","right":true},{"lg":"nba","n":"Tony Parker","y":2001,"rd":1,"pk":28,"tm":"San Antonio Spurs","col":"No college (international)","pos":"Guard","size":"6-2, 185 lb","g":1254,"stat":"15.5 points, 2.7 rebounds, 5.6 assists a game","hon":["6x All-Star","Hall of Fame"],"kind":"steal","v":111.2,"id":"parketo01","angle":"pan","rep":"Teenage point guard from an overseas pro league who weighs roughly as much as a carry-on bag. Lightning in the open floor, but the jumper is an unsolved case and the defense is a polite suggestion. Any legitimately physical workout partner will fold him like a lawn chair. Speed is nice; strength is mandatory, and he has not met it yet.","proj":"Projection: two-year project, then back overseas running a club team.","right":false},{"lg":"nba","n":"Gilbert Arenas","y":2001,"rd":2,"pk":31,"tm":"Golden State Warriors","col":"Arizona","pos":"Guard","size":"6-4, 191 lb","g":552,"stat":"20.7 points, 3.9 rebounds, 5.3 assists a game","hon":["3x All-Star"],"kind":"steal","v":51.2,"id":"arenagi01","angle":"pan","rep":"Undersized scoring guard who is not a point guard, not quite tall enough to be a shooting guard, and somehow confident enough to be both. Shot selection is best described as interpretive. Fast, aggressive, and loves the ball the way some people love their phones. Teams will call him a tweener, and then they will call the next name.","proj":"Projection: second-round scorer. Shoots his way off a roster by December.","right":false},{"lg":"nba","n":"Hedo Türkoğlu","y":2000,"rd":1,"pk":16,"tm":"Sacramento Kings","col":"No college (international)","pos":"Forward","size":"6-10, 220 lb","g":997,"stat":"11.1 points, 4.0 rebounds, 2.8 assists a game","hon":[],"kind":"steal","v":63.3,"id":"turkohe01","angle":"pan","rep":"Lanky, slow-footed overseas forward who looks like a math teacher who wandered into an open run. Can handle, can pass, has some size, but his defense is a sequence of polite waves at players going past him. The frame is narrow, the foot speed is glacial, and the jumper has more release points than a mixtape. Classic draft-night mystery box.","proj":"Projection: three years on the bench, then a lengthy overseas encore.","right":false},{"lg":"nba","n":"Michael Redd","y":2000,"rd":2,"pk":43,"tm":"Milwaukee Bucks","col":"Ohio State","pos":"Guard","size":"6-6, 220 lb","g":629,"stat":"19.0 points, 3.8 rebounds, 2.1 assists a game","hon":["1x All-Star"],"kind":"steal","v":55.8,"id":"reddmi01","angle":"pan","rep":"Lefty scorer leaving school early after three seasons of firing away, with three-point percentages that made everyone in the building nervous. Strong frame and can get buckets inside, but the jumper is erratic and the defense is an afterthought he never got around to. A wing who cannot shoot is a scout's worst nightmare, and this one shoots constantly.","proj":"Projection: deep bench. Garbage-time chucker with a long memory.","right":false},{"lg":"nba","n":"Jarrett Culver","y":2019,"rd":1,"pk":6,"tm":"Phoenix Suns","col":"Texas Tech","pos":"Guard","size":"6-6, 195 lb","g":144,"stat":"6.5 points, 2.8 rebounds, 1.2 assists a game","hon":[],"kind":"bust","v":-0.1,"id":"culveja01","angle":"glow","rep":"Went from bench piece to the guy running every late-clock possession in a single offseason, a growth curve that should frighten the league. Long, wiry wing who defends like he has a personal grudge against the opposing scorer. The jumper has a few moving parts, but the release looked better every week, and players who improve this fast do not stop. Carried a deep tournament run without breaking a sweat.","proj":"Projection: franchise wing. Already measuring the rafters for his banner.","right":false},{"lg":"nba","n":"Luka Dončić","y":2018,"rd":1,"pk":3,"tm":"Atlanta Hawks","col":"No college (international)","pos":"Guard / Forward","size":"6-8, 230 lb","g":514,"stat":"29.2 points, 8.5 rebounds, 8.2 assists a game","hon":["6x All-Star"],"kind":"star","v":66.6,"id":"doncilu01","angle":"glow","rep":"Plays with the unhurried calm of a man who has been doing this against grown professionals since middle school. Not a burner, and his vertical will not make the highlight reel, but he gets to every spot he wants by simply deciding to. Sees passing lanes before they exist and manipulates defenders like a chess hustler in the park. Has the size of a forward and the vision of a point guard.","proj":"Projection: perennial MVP candidate. Will also lobby officials at an elite level.","right":true},{"lg":"nba","n":"Markelle Fultz","y":2017,"rd":1,"pk":1,"tm":"Philadelphia 76ers","col":"Washington","pos":"Guard","size":"6-4, 209 lb","g":260,"stat":"10.2 points, 3.1 rebounds, 4.3 assists a game","hon":[],"kind":"bust","v":8.2,"id":"fultzma01","angle":"glow","rep":"Smooth combo guard who scores at all three levels with a jumper so pure it should be preserved in a museum. Changes speeds like a sports car with a perfect clutch, then finishes with either hand. Put up gaudy numbers on a losing team, which only proves he did it with zero help. The shooting stroke alone is worth the price of admission and will never, ever need adjustment.","proj":"Projection: franchise point guard for fifteen years. The jumper is bulletproof.","right":false},{"lg":"nba","n":"Jayson Tatum","y":2017,"rd":1,"pk":3,"tm":"Boston Celtics","col":"Duke","pos":"Forward","size":"6-8, 210 lb","g":601,"stat":"23.5 points, 7.4 rebounds, 3.9 assists a game","hon":["6x All-Star"],"kind":"star","v":67.1,"id":"tatumja01","angle":"glow","rep":"Polished scorer with a footwork package that looks borrowed from a fifteen-year veteran. Lives in the midrange like he has a mortgage there and can get to his spot against any defender alive. Long, smooth, and still filling out, with a three-point stroke that kept improving as the season went. Some question whether he passes enough. Those people will be explaining themselves later.","proj":"Projection: perennial All-NBA. Will win something big before the doubters log off.","right":true},{"lg":"nba","n":"Josh Jackson","y":2017,"rd":1,"pk":4,"tm":"Phoenix Suns","col":"Kansas","pos":"Forward / Guard","size":"6-8, 207 lb","g":291,"stat":"11.3 points, 4.0 rebounds, 1.8 assists a game","hon":[],"kind":"bust","v":-1.8,"id":"jacksjo02","angle":"glow","rep":"Explosive wing who plays every possession like it owes him money. Elite athlete, relentless defender, and the kind of competitor who would dive for a loose ball in a pickup game. The jumper has a hitch, but he made strides all year and the work ethic suggests it gets fixed by Thanksgiving. Was the top-rated high school player in his class for a reason, and the reason is everything.","proj":"Projection: two-way All-Star. Some will call him the best player in this draft.","right":false},{"lg":"nba","n":"Jaylen Brown","y":2016,"rd":1,"pk":3,"tm":"Boston Celtics","col":"California","pos":"Forward / Guard","size":"6-6, 223 lb","g":674,"stat":"20.0 points, 5.5 rebounds, 2.9 assists a game","hon":["5x All-Star"],"kind":"star","v":47.5,"id":"brownja02","angle":"pan","rep":"Built like a light heavyweight and runs like one too, but basketball is unfortunately played with a ball. The jumper is a rumor, the handle is a dare, and the free throw shooting suggests the rim keeps moving on him. Spends a lot of time attacking the basket in a straight line, which works until the defense learns to stand there. Reportedly reads a lot. Concerning.","proj":"Projection: athletic bench wing. Will dunk in warmups and little else.","right":false},{"lg":"nba","n":"Dragan Bender","y":2016,"rd":1,"pk":4,"tm":"Phoenix Suns","col":"No college (international)","pos":"Forward","size":"7-0, 249 lb","g":187,"stat":"5.4 points, 3.9 rebounds, 1.3 assists a game","hon":[],"kind":"bust","v":0.6,"id":"bendedr01","angle":"glow","rep":"Seven-footer who handles, passes, and shoots like a guard, which is the exact sentence every front office dreams of reading. Barely played for his pro club, but that only means the tape is all upside and no evidence. Slides his feet on the perimeter like a wing and is still a teenager, so the frame will fill out any minute now. The modern big man, arriving right on schedule.","proj":"Projection: the mythical creature everyone else wishes they had drafted.","right":false},{"lg":"nba","n":"Karl-Anthony Towns","y":2015,"rd":1,"pk":1,"tm":"Minnesota Timberwolves","col":"Kentucky","pos":"Center / Forward","size":"7-0, 248 lb","g":720,"stat":"22.8 points, 11.1 rebounds, 3.1 assists a game","hon":["6x All-Star"],"kind":"star","v":94.8,"id":"townska01","angle":"glow","rep":"Seven-footer with soft hands, a feathery jumper, and post footwork that looks choreographed. Played limited minutes on a stacked roster, which hid nothing and revealed everything. Can face up, step out, protect the rim, and pass out of double teams like a guard trapped in a center's body. Young for the class and skilled beyond it, he is the rare big who checks every box on the form.","proj":"Projection: perennial All-Star big man. Stretches the floor to the parking lot.","right":true},{"lg":"nba","n":"Jahlil Okafor","y":2015,"rd":1,"pk":3,"tm":"Philadelphia 76ers","col":"Duke","pos":"Center / Forward","size":"6-10, 270 lb","g":248,"stat":"10.3 points, 4.7 rebounds, 0.9 assists a game","hon":[],"kind":"bust","v":7.1,"id":"okafoja01","angle":"pan","rep":"The most polished low-post scorer in years, which is a little like being the best fax machine repairman in the country. Has a drop step from a different decade and soft hands, but defends the pick and roll as if it were a rumor he once overheard. Rarely leaves the paint on either end. Free throws are an adventure the whole family can enjoy.","proj":"Projection: big numbers on bad teams. Born roughly twenty years too late.","right":true},{"lg":"nba","n":"Mario Hezonja","y":2015,"rd":1,"pk":5,"tm":"Orlando Magic","col":"No college (international)","pos":"Forward / Guard","size":"6-8, 220 lb","g":330,"stat":"6.9 points, 3.1 rebounds, 1.3 assists a game","hon":[],"kind":"bust","v":3.2,"id":"hezonma01","angle":"glow","rep":"Athletic wing with a jumper that looks effortless and a confidence level that could power a small city. Played sparingly for one of the best clubs on his continent, which only means his coach was hiding a weapon. Explodes to the rim, shoots off movement, and carries himself like a guy who has already made three All-Star teams in his head. The personality alone sells tickets.","proj":"Projection: high-flying All-Star scorer. He will tell you so personally.","right":false},{"lg":"nba","n":"Jabari Parker","y":2014,"rd":1,"pk":2,"tm":"Milwaukee Bucks","col":"Duke","pos":"Forward","size":"6-7, 245 lb","g":310,"stat":"14.1 points, 5.5 rebounds, 2.0 assists a game","hon":[],"kind":"bust","v":13.7,"id":"parkeja01","angle":"glow","rep":"The most NBA-ready scorer in the class, a forward who gets a bucket from anywhere using a bag of moves usually seen on thirty-year-olds. Strong, skilled, and equally comfortable facing up or backing down. Defense is a work in progress, but you do not draft a guy like this to stop people. Has been a household name since his early teens and has never once wilted under it.","proj":"Projection: Rookie of the Year, then twenty-five a night for a decade.","right":false},{"lg":"nba","n":"Joel Embiid","y":2014,"rd":1,"pk":3,"tm":"Philadelphia 76ers","col":"Kansas","pos":"Center","size":"7-0, 280 lb","g":490,"stat":"27.6 points, 10.8 rebounds, 3.7 assists a game","hon":["7x All-Star"],"kind":"star","v":68.9,"id":"embiijo01","angle":"glow","rep":"Has played organized basketball for roughly as long as most prospects have been driving, and already moves like a ballet dancer stuffed into a seven-footer. Footwork is absurd, shot blocking is instinctive, and the touch says a jumper is coming. Back and foot issues are the one cloud in the sky, but you do not pass on talent this rare. Apparently learned post moves from watching tape on fast forward.","proj":"Projection: franchise center and MVP candidate, assuming he can stay upright.","right":true},{"lg":"nba","n":"Dante Exum","y":2014,"rd":1,"pk":5,"tm":"Utah Jazz","col":"No college (international)","pos":"Guard","size":"6-5, 214 lb","g":320,"stat":"6.2 points, 1.9 rebounds, 2.3 assists a game","hon":[],"kind":"bust","v":6.6,"id":"exumda01","angle":"glow","rep":"Mystery man with tape to match: grainy footage of a long, lightning-quick lead guard slicing through defenders who appear to be extras. Six-foot-six at the point with a first step that arrives before the defense hears it. Has not played college or high-level pro ball, so the jumper is theoretical and the upside is unlimited. Front offices describe him in terms usually reserved for sports cars.","proj":"Projection: franchise point guard. The mystery is the best part.","right":false},{"lg":"nba","n":"Anthony Bennett","y":2013,"rd":1,"pk":1,"tm":"Cleveland Cavaliers","col":"UNLV","pos":"Forward","size":"6-8, 245 lb","g":151,"stat":"4.4 points, 3.1 rebounds, 0.5 assists a game","hon":[],"kind":"bust","v":0.5,"id":"bennean01","angle":"pan","rep":"A tweener in the purest sense: too small to bang inside, not quick enough to guard on the wing, and unable to work out for anyone thanks to a shoulder that needed surgery. Can score in bunches against mid-major size, which is a sentence doing heavy lifting. Defensive effort comes and goes like a bus schedule. Conditioning is listed as a work in progress.","proj":"Projection: late lottery talent in a weak class. Someone will reach anyway.","right":true},{"lg":"nba","n":"Anthony Davis","y":2012,"rd":1,"pk":1,"tm":"New Orleans Hornets","col":"Kentucky","pos":"Forward / Center","size":"6-10, 253 lb","g":807,"stat":"24.0 points, 10.7 rebounds, 2.6 assists a game","hon":["10x All-Star"],"kind":"star","v":120.0,"id":"davisan02","angle":"glow","rep":"Was a guard until a growth spurt turned him into a seven-footer who still handles and passes like one. Blocks shots like it is a personal hobby, runs the floor like a gazelle, and changes every possession on defense without leaving his spot. The frame is skinny and the offense raw, but those are the only two nitpicks, and both are temporary. Generational is an overused word. Not here.","proj":"Projection: generational two-way big. Every team in the lottery is praying.","right":true},{"lg":"nba","n":"Dion Waiters","y":2012,"rd":1,"pk":4,"tm":"Cleveland Cavaliers","col":"Syracuse","pos":"Guard","size":"6-3, 215 lb","g":419,"stat":"13.1 points, 2.6 rebounds, 2.8 assists a game","hon":[],"kind":"bust","v":8.7,"id":"waitedi01","angle":"glow","rep":"Bulldog scorer who came off the bench and still looked like the best guard on the floor. Built like a running back, gets into the paint at will, and has the swagger of a man who has never missed a shot in his own memory. Never started a game, which only proves he does not need the lights on to perform. Confidence is a skill, and he has the most in the building.","proj":"Projection: star scoring guard. Will shoot his way out of any slump.","right":false},{"lg":"nba","n":"Thomas Robinson","y":2012,"rd":1,"pk":5,"tm":"Sacramento Kings","col":"Kansas","pos":"Forward","size":"6-10, 237 lb","g":313,"stat":"4.9 points, 4.8 rebounds, 0.6 assists a game","hon":[],"kind":"bust","v":4.5,"id":"robinth01","angle":"glow","rep":"Relentless power forward with a body chiseled out of granite and a motor that never idles. Rebounds out of his area like the ball is personally addressed to him and finishes through contact with bad intentions. Was an afterthought one season and a national player of the year candidate the next. The jumper is still under construction, but you simply cannot teach this kind of energy.","proj":"Projection: double-double machine for a decade. Will outwork the entire league.","right":false},{"lg":"nba","n":"Kyrie Irving","y":2011,"rd":1,"pk":1,"tm":"Cleveland Cavaliers","col":"Duke","pos":"Guard","size":"6-2, 195 lb","g":779,"stat":"23.7 points, 4.1 rebounds, 5.6 assists a game","hon":["9x All-Star"],"kind":"star","v":90.9,"id":"irvinky01","angle":"glow","rep":"Played only a handful of college games before a foot injury, and that handful was enough to make every front office reshuffle its board. Has a handle that seems illegal in at least three states, finishes off the glass with either hand from angles that should not exist, and shoots it with range. Small sample, enormous talent. Do not overthink this one.","proj":"Projection: franchise point guard and a nightly highlight reel.","right":true},{"lg":"nba","n":"Jan Veselý","y":2011,"rd":1,"pk":6,"tm":"Washington Wizards","col":"No college (international)","pos":"Forward","size":"6-11, 240 lb","g":162,"stat":"3.6 points, 3.5 rebounds, 0.6 assists a game","hon":[],"kind":"bust","v":4.0,"id":"veselja01","angle":"glow","rep":"Seven-footer who runs the floor like a wing and dunks like he is trying to break the backboard as a personal statement. Athleticism at his size is rare anywhere and borderline unheard of on his league's grainy broadcast feeds. The shooting needs work, free throws especially, but you can teach a stroke. You cannot teach a seven-footer who plays above the rim like this.","proj":"Projection: high-flying starter at the four. Highlight machine for years.","right":false},{"lg":"nba","n":"John Wall","y":2010,"rd":1,"pk":1,"tm":"Washington Wizards","col":"Kentucky","pos":"Guard","size":"6-3, 210 lb","g":647,"stat":"18.7 points, 4.2 rebounds, 8.9 assists a game","hon":["5x All-Star"],"kind":"star","v":44.4,"id":"walljo01","angle":"glow","rep":"Fastest player with the ball in his hands in the entire sport, possibly in several sports. Gets coast to coast in about four dribbles and finishes with a flair that will sell season tickets on its own. The jumper is streaky and he turns it over, but that is what happens when your brain moves this fast. Plays like a guy who knows the cameras are following him, because they are.","proj":"Projection: franchise point guard. Fastest man in the league on day one.","right":true},{"lg":"nba","n":"Wesley Johnson","y":2010,"rd":1,"pk":4,"tm":"Minnesota Timberwolves","col":"Syracuse","pos":"Forward / Guard","size":"6-7, 215 lb","g":609,"stat":"7.0 points, 3.2 rebounds, 1.1 assists a game","hon":[],"kind":"bust","v":10.7,"id":"johnswe01","angle":"glow","rep":"Long, smooth wing who can shoot it, defend multiple spots, and rise over the top for a dunk in traffic. Has an effortless stroke from deep and a physical maturity that makes him ready from the opening tip. Some will mention his age, but experience is a feature, not a bug. Projects as a plug-and-play starter who will be very good for a very long time.","proj":"Projection: perennial starting wing. The safest pick in the top five.","right":false},{"lg":"nba","n":"Ekpe Udoh","y":2010,"rd":1,"pk":6,"tm":"Golden State Warriors","col":"Baylor","pos":"Center / Forward","size":"6-10, 245 lb","g":384,"stat":"3.5 points, 2.9 rebounds, 0.7 assists a game","hon":[],"kind":"bust","v":10.6,"id":"udohek01","angle":"pan","rep":"Long-armed shot blocker who is already twenty-three, which in prospect years is roughly retirement age. Defends the rim with genuine instincts but treats the offensive end like a place he visits on weekends. Has one great season on his resume, much of it achieved against people years younger. Fine backup big. Drafting him in the top ten would certainly be a choice.","proj":"Projection: rotation big who blocks shots and confuses the box score.","right":true},{"lg":"nba","n":"Blake Griffin","y":2009,"rd":1,"pk":1,"tm":"Los Angeles Clippers","col":"Oklahoma","pos":"Forward / Center","size":"6-9, 250 lb","g":765,"stat":"19.0 points, 8.0 rebounds, 4.0 assists a game","hon":["6x All-Star"],"kind":"star","v":81.0,"id":"griffbl01","angle":"glow","rep":"Throws down dunks with a violence that should require a permit. Freakish leaper for his size, explosive off one or two feet, and a monster on the glass who simply outjumps everyone in the zip code. The jumper is a rough draft and the free throws need work, but this is the most dominant college big in years. Has the motor of a sports car and the build of a moving van.","proj":"Projection: franchise power forward. Will put somebody on a poster weekly.","right":true},{"lg":"nba","n":"Hasheem Thabeet","y":2009,"rd":1,"pk":2,"tm":"Memphis Grizzlies","col":"UConn","pos":"Center","size":"7-3, 263 lb","g":224,"stat":"2.2 points, 2.7 rebounds, 0.1 assists a game","hon":[],"kind":"bust","v":4.8,"id":"thabeha01","angle":"pan","rep":"Very tall. That is the report. Blocks shots because the ball keeps wandering into the space he occupies, but on offense he looks like a man assembling furniture without the instructions. Raw does not begin to cover it. The hands are unreliable, the footwork is still being installed, and he gets moved off his spot by smaller players who simply lean on him.","proj":"Projection: tallest backup center in the league. Excellent at standing near the rim.","right":true},{"lg":"nba","n":"James Harden","y":2009,"rd":1,"pk":3,"tm":"Oklahoma City Thunder","col":"Arizona State","pos":"Guard","size":"6-5, 220 lb","g":1221,"stat":"24.0 points, 5.6 rebounds, 7.3 assists a game","hon":["11x All-Star"],"kind":"star","v":182.3,"id":"hardeja01","angle":"pan","rep":"Plays below the rim and slower than he looks, which is saying something, because he looks slow. Lacks the explosion to beat elite athletes off the dribble and survives on change of pace and craftiness, tricks that tend to stop working against grown men. Defense is a philosophical question. A bulky lefty who might top out as a nice sixth man with a crafty floater.","proj":"Projection: useful bench scorer. Nobody is building an offense around this.","right":false},{"lg":"nba","n":"Jonny Flynn","y":2009,"rd":1,"pk":6,"tm":"Minnesota Timberwolves","col":"Syracuse","pos":"Guard","size":"6-0, 185 lb","g":163,"stat":"9.2 points, 1.9 rebounds, 3.9 assists a game","hon":[],"kind":"bust","v":-1.1,"id":"flynnjo01","angle":"glow","rep":"Lightning-quick point guard with a motor that apparently runs on pure caffeine. Has the stamina to play an entire tournament weekend and look fresher at the end than the referees. Breaks down defenders in a phone booth, gets to the rim whenever he wants, and leads with the kind of fire you cannot teach. Small, sure, but every great little guard was small at some point.","proj":"Projection: franchise point guard. Clearly the best guard in this draft.","right":false},{"lg":"nba","n":"Greg Oden","y":2007,"rd":1,"pk":1,"tm":"Portland Trail Blazers","col":"Ohio State","pos":"Center","size":"7-0, 250 lb","g":105,"stat":"8.0 points, 6.2 rebounds, 0.5 assists a game","hon":[],"kind":"bust","v":7.3,"id":"odengr01","angle":"glow","rep":"A once-in-a-generation center who looks thirty-five and plays like he invented rim protection. Alters every shot within ten feet, owns the glass, and made a deep tournament run while shooting free throws with his off hand. Already has the strength of a veteran and the instincts of a Hall of Famer. Some prefer the skinny scorer. Those people do not understand winning.","proj":"Projection: decade-long anchor of a champion. The obvious first pick.","right":false},{"lg":"nba","n":"Kevin Durant","y":2007,"rd":1,"pk":2,"tm":"Seattle SuperSonics","col":"Texas","pos":"Forward / Guard","size":"6-11, 240 lb","g":1201,"stat":"27.1 points, 6.9 rebounds, 4.4 assists a game","hon":["16x All-Star"],"kind":"star","v":186.2,"id":"duranke01","angle":"glow","rep":"Seven-foot wingspan, guard skills, and a jumper that goes in from any spot on the floor, including some spots that are not technically on the floor. Scored at a historic rate as a freshman and made it look like a casual pickup run. The frame is pencil thin and the weight room has not been kind, but nobody ever won a scoring title by lifting a car. A pure bucket.","proj":"Projection: multiple scoring titles. The skinny kid will be just fine.","right":true},{"lg":"nba","n":"Al Horford","y":2007,"rd":1,"pk":3,"tm":"Atlanta Hawks","col":"Florida","pos":"Center / Forward","size":"6-8, 240 lb","g":1183,"stat":"12.7 points, 7.7 rebounds, 3.2 assists a game","hon":["5x All-Star"],"kind":"star","v":119.5,"id":"horfoal01","angle":"glow","rep":"The adult in every room. Proven winner on the biggest stage who does every unglamorous thing right: sets bruising screens, makes the extra pass, and defends the pick and roll like he wrote the coverage. Not flashy, not loud, just relentlessly correct. Can step out and shoot it a little, and the feel suggests a lot more is coming. Will still be winning playoff games when his classmates are coaching.","proj":"Projection: perennial All-Star big. Meaningful minutes well into his late thirties.","right":true},{"lg":"nba","n":"Yi Jianlian","y":2007,"rd":1,"pk":6,"tm":"Milwaukee Bucks","col":"No college (international)","pos":"Forward","size":"7-0, 240 lb","g":272,"stat":"7.9 points, 4.9 rebounds, 0.7 assists a game","hon":[],"kind":"bust","v":3.1,"id":"jianlyi01","angle":"glow","rep":"Seven-footer who runs like a deer and splashes jumpers from the elbow with a release that looks lifted from a guard. Dominated his pro league with athleticism you rarely see at his size. Footage is limited and private workouts were, let us say, selective, but the glimpses are breathtaking. A face-up big who could change how teams think about the four.","proj":"Projection: All-Star stretch four. Mismatch nightmare from day one.","right":false},{"lg":"nba","n":"LaMarcus Aldridge","y":2006,"rd":1,"pk":2,"tm":"Chicago Bulls","col":"Texas","pos":"Forward / Center","size":"6-11, 250 lb","g":1076,"stat":"19.1 points, 8.1 rebounds, 1.9 assists a game","hon":["7x All-Star"],"kind":"star","v":115.5,"id":"aldrila01","angle":"glow","rep":"Long, mobile big with soft touch, a high release, and a turnaround jumper that is basically unguardable at his height. Runs the floor, protects the rim, and has a frame that will carry another twenty pounds of muscle without losing a step. Polished enough to play now and still nowhere near his ceiling. The kind of big man coaches happily build an offense around.","proj":"Projection: multi-time All-Star. Will live on the left block for a decade.","right":true},{"lg":"nba","n":"Adam Morrison","y":2006,"rd":1,"pk":3,"tm":"Charlotte Bobcats","col":"Gonzaga","pos":"Forward","size":"6-8, 205 lb","g":161,"stat":"7.5 points, 2.1 rebounds, 1.4 assists a game","hon":[],"kind":"bust","v":-1.5,"id":"morriad01","angle":"pan","rep":"Can score from anywhere against anyone, which is fortunate, because he will need to score twice as much as he gives up. Moves laterally like a filing cabinet, lacks the burst to separate from NBA wings, and defends with the urgency of a man waiting for a table. Elite shooter, elite competitor, and the athleticism of a guy who drives a minivan to the gym.","proj":"Projection: college legend. Struggles mightily once everyone is an athlete.","right":true},{"lg":"nba","n":"Tyrus Thomas","y":2006,"rd":1,"pk":4,"tm":"Portland Trail Blazers","col":"LSU","pos":"Forward","size":"6-9, 215 lb","g":402,"stat":"7.7 points, 4.8 rebounds, 0.9 assists a game","hon":[],"kind":"bust","v":12.9,"id":"thomaty01","angle":"glow","rep":"Leaps like the court is a trampoline and blocks shots from angles that defy physics. Came out of nowhere to become the most explosive athlete in the entire draft, and he is still learning the game, which is terrifying for opponents. Raw offensively, sure, but you cannot teach a vertical like this. The upside is a perennial Defensive Player of the Year who dunks on your head.","proj":"Projection: defensive monster and highlight machine. The potential is limitless.","right":false},{"lg":"nba","n":"Shelden Williams","y":2006,"rd":1,"pk":5,"tm":"Atlanta Hawks","col":"Duke","pos":"Forward","size":"6-9, 250 lb","g":361,"stat":"4.5 points, 4.3 rebounds, 0.5 assists a game","hon":[],"kind":"bust","v":9.9,"id":"willish02","angle":"glow","rep":"Battle-tested four-year big who treats the paint like a place of business and rebounds as if every miss owes him back pay. Elite shot blocker, physical, mature, and ready to contribute from day one. Not the highest ceiling in the class, but the floor is a sturdy, dependable starter who does the dirty work for fifteen years. In a draft full of mysteries, he is a sure thing.","proj":"Projection: reliable starting big for fifteen years. Zero chance he misses.","right":false},{"lg":"nba","n":"Dwight Howard","y":2004,"rd":1,"pk":1,"tm":"Orlando Magic","col":"No college (international)","pos":"Center","size":"6-10, 265 lb","g":1242,"stat":"15.7 points, 11.8 rebounds, 1.3 assists a game","hon":["8x All-Star","Hall of Fame"],"kind":"star","v":142.0,"id":"howardw01","angle":"glow","rep":"Built like a linebacker straight out of high school, with shoulders that look borrowed from a much older man. Runs, jumps, rebounds, and blocks shots with a blend of size and explosion that has scouts reaching for the thesaurus. The offensive game is raw and the post moves are mostly theoretical, but nobody this young has looked this physically ready. The smile alone could sell out an arena.","proj":"Projection: franchise center and perennial Defensive Player of the Year.","right":true},{"lg":"nba","n":"LeBron James","y":2003,"rd":1,"pk":1,"tm":"Cleveland Cavaliers","col":"No college (international)","pos":"Forward / Guard","size":"6-9, 250 lb","g":1622,"stat":"26.8 points, 7.5 rebounds, 7.4 assists a game","hon":["22x All-Star"],"kind":"star","v":276.9,"id":"jamesle01","angle":"glow","rep":"The most scrutinized teenager the sport has ever produced, and somehow he has exceeded the coverage. Built like a grown man, sees the floor like a veteran point guard, and finishes through contact like a tight end. There is no weakness worth listing, and mentioning the jumper feels petty. Front offices have been tanking in their hearts for two years.","proj":"Projection: all-time great. Possibly still playing when your kids get drafted.","right":true},{"lg":"nba","n":"Darko Miličić","y":2003,"rd":1,"pk":2,"tm":"Detroit Pistons","col":"No college (international)","pos":"Forward / Center","size":"7-0, 250 lb","g":468,"stat":"6.0 points, 4.2 rebounds, 0.9 assists a game","hon":[],"kind":"bust","v":7.0,"id":"milicda01","angle":"glow","rep":"Seven-footer with soft hands, a lefty touch, and the mobility of a wing, still a teenager and already battling grown pros. Every workout has scouts walking out in stunned silence. Not much game footage exists, but the glimpses suggest a modern big who can do everything. The rare prospect who would go first overall in any normal draft, and some think that sells him short.","proj":"Projection: franchise big man. Teams will regret passing on him for years.","right":false},{"lg":"nba","n":"Carmelo Anthony","y":2003,"rd":1,"pk":3,"tm":"Denver Nuggets","col":"Syracuse","pos":"Forward","size":"6-7, 238 lb","g":1260,"stat":"22.5 points, 6.2 rebounds, 2.7 assists a game","hon":["10x All-Star","Hall of Fame"],"kind":"star","v":108.6,"id":"anthoca01","angle":"glow","rep":"Led his team to a title as a freshman by scoring from every spot on the floor in every way available. Big, strong forward with a jab step that freezes defenders like they have been unplugged. Can post smaller wings, face up bigger forwards, and will shoot his team into or out of anything. The most NBA-ready scorer in the class. It is not close.","proj":"Projection: perennial scoring champion. Will hold the ball and make it worth it.","right":true},{"lg":"nba","n":"Yao Ming","y":2002,"rd":1,"pk":1,"tm":"Houston Rockets","col":"No college (international)","pos":"Center","size":"7-6, 310 lb","g":486,"stat":"19.0 points, 9.2 rebounds, 1.6 assists a game","hon":["8x All-Star","Hall of Fame"],"kind":"star","v":66.0,"id":"mingya01","angle":"glow","rep":"Stands well over seven and a half feet with the touch of a guard, a soft jumper, and passing instincts that make no sense for a man who ducks through doorways. Has dominated his pro league for years and moves far better than a body this size has any right to. Strength needs work against NBA brutes, but the skill level is otherworldly. A matchup problem every single night.","proj":"Projection: perennial All-Star center. Will need a custom everything.","right":true},{"lg":"nba","n":"Jay Williams","y":2002,"rd":1,"pk":2,"tm":"Chicago Bulls","col":"Duke","pos":"Guard","size":"6-2, 195 lb","g":75,"stat":"9.5 points, 2.6 rebounds, 4.7 assists a game","hon":[],"kind":"bust","v":0.8,"id":"willija03","angle":"glow","rep":"Explosive lead guard with a championship on his resume and a national player of the year trophy on his shelf. Scores in bunches, pushes the pace, and carries a winner's poise that never wavers. Can get to the rim or pull up from deep, and already plays like a ten-year veteran. The safest bet in the lottery to become a star, no questions asked.","proj":"Projection: franchise point guard. An All-Star within three seasons.","right":false},{"lg":"nba","n":"Nikoloz Tskitishvili","y":2002,"rd":1,"pk":5,"tm":"Denver Nuggets","col":"No college (international)","pos":"Forward","size":"7-0, 225 lb","g":172,"stat":"2.9 points, 1.8 rebounds, 0.7 assists a game","hon":[],"kind":"bust","v":-1.6,"id":"tskitni01","angle":"glow","rep":"Seven-footer who can shoot from deep, handle in transition, and run the floor like a guard. Only a teenager and already getting minutes for a pro team in a serious league, the kind of experience that ages prospects in the best way. The stroke in workouts was so pure some scouts thought they were watching a wing. Pencil thin, sure, but the weight room fixes that.","proj":"Projection: the next great stretch big. Opposing centers will hate it.","right":false},{"lg":"nba","n":"Dajuan Wagner","y":2002,"rd":1,"pk":6,"tm":"Cleveland Cavaliers","col":"Memphis","pos":"Guard","size":"6-2, 200 lb","g":103,"stat":"9.4 points, 1.4 rebounds, 1.9 assists a game","hon":[],"kind":"bust","v":-0.0,"id":"wagneda02","angle":"glow","rep":"Pure bucket-getter who once poured in a point total in a high school game that still reads like a typo. Fearless, quick, and capable of scoring from anywhere on the floor. Undersized for the two, but nobody has stopped him long enough to prove it matters. A born scorer who plays with the confidence of a guy who has never once been benched.","proj":"Projection: twenty-point scorer by year two. Bucket-getter for life.","right":false},{"lg":"nba","n":"Pau Gasol","y":2001,"rd":1,"pk":3,"tm":"Atlanta Hawks","col":"No college (international)","pos":"Center / Forward","size":"7-0, 250 lb","g":1226,"stat":"17.0 points, 9.2 rebounds, 3.2 assists a game","hon":["6x All-Star","Hall of Fame"],"kind":"star","v":143.9,"id":"gasolpa01","angle":"pan","rep":"Seven-footer with skill, but the frame of a coat rack and the physicality of a library card. Has nice touch and passing instincts, yet every tape shows him getting shoved off his spot by bigger, angrier men. Played in a league where the defense apparently takes long lunch breaks. Will need to add thirty pounds just to avoid being blown over by the air conditioning.","proj":"Projection: finesse backup big. Soft hands, softer everything else.","right":false},{"lg":"nba","n":"Darius Miles","y":2000,"rd":1,"pk":3,"tm":"Los Angeles Clippers","col":"No college (international)","pos":"Forward","size":"6-9, 210 lb","g":446,"stat":"10.1 points, 4.9 rebounds, 1.9 assists a game","hon":[],"kind":"bust","v":9.5,"id":"milesda01","angle":"glow","rep":"Straight out of high school with arms that stretch across zip codes and a bounce that makes him look like he is wearing springs. Athletic, versatile, and fearless, he can handle, pass, block shots, and guard multiple positions. The jumper is a rumor, but with tools like these, the skill will follow. Already has the confidence of a star and the highlights to back it up.","proj":"Projection: franchise forward and the face of a new era.","right":false},{"lg":"nba","n":"Marcus Fizer","y":2000,"rd":1,"pk":4,"tm":"Chicago Bulls","col":"Iowa State","pos":"Forward","size":"6-9, 262 lb","g":289,"stat":"9.6 points, 4.6 rebounds, 1.2 assists a game","hon":[],"kind":"bust","v":2.7,"id":"fizerma01","angle":"glow","rep":"Powerful forward who bullies people around the rim and can step out and knock down a midrange jumper on the side. Dominant college resume, physically ready, and the kind of soft touch that suggests he will be scoring in the league from his first night. Undersized for the post, but strength and skill like this make that irrelevant. The safest scorer in the class.","proj":"Projection: twenty-and-ten forward. Plug him in and enjoy.","right":false},{"lg":"nba","n":"DerMarr Johnson","y":2000,"rd":1,"pk":6,"tm":"Atlanta Hawks","col":"Cincinnati","pos":"Forward","size":"6-9, 201 lb","g":344,"stat":"6.2 points, 2.2 rebounds, 0.9 assists a game","hon":[],"kind":"bust","v":6.4,"id":"johnsde03","angle":"glow","rep":"Long, silky wing with a beautiful shooting stroke and the kind of length that makes closeouts pointless. Only one season in college and already looks like a natural scorer at the next level. The frame is thin, but the skill and polish are rare for his age. Some see a future All-Star wing, and those people are probably right.","proj":"Projection: smooth starting wing for a decade. Pure shooter.","right":false}];
